255	            background-color: var(--table-header-color);
256	            border: 1px solid var(--border-color);
257	        }
258	
259	        /* The row under mouse pointer is highlight for better legibility. */
260	        tr:hover, tr:hover td
261	        {
262	            background-color: var(--table-hover-color);
263	        }
264	
265	        tr:hover
266	        {
267	            box-shadow: 0 0 1rem rgba(0, 0, 0, 0.1);
268	        }
269	
270	        #error
271	        {
272	            background: var(--error-color);
273	            white-space: pre-wrap;
274	            padding: 0.5rem 1rem;
275	            display: none;
276	        }
277	
278	        /* When mouse pointer is over table cell, will display full text (with wrap) instead of cut. */
279	        td.left:hover
280	        {
281	            white-space: pre-wrap;
282	            max-width: none;
283	        }
284	
285	        td.transposed
286	        {
287	            max-width: none;
288	            overflow: auto;
289	            white-space: pre-wrap;
290	        }
291	
292	        td.empty-result
293	        {
294	            text-align: center;
295	            vertical-align: middle;
296	        }
297	
298	        div.empty-result
299	        {
300	            opacity: 10%;
301	            font-size: 7vw;
302	            font-family: Liberation Sans, DejaVu Sans, sans-serif;
303	        }
304	
305	        /* The style for SQL NULL */
306	        .null
307	        {
308	            color: var(--null-color);
309	        }
310	
311	        @keyframes hourglass-animation {
312	            0% {
313	                transform: rotate(-180deg);
314	            }
315	            50% {
316	                transform: rotate(-180deg);
317	            }
318	            100% {
319	                transform: none;
320	            }
321	        }
322	
323	        #hourglass
324	        {
325	            display: none;
326	            margin-left: 1rem;
327	            font-size: 110%;
328	            color: #888;
329	            animation: hourglass-animation 1s linear infinite;
330	        }
331	
332	        #check-mark
333	        {
334	            display: none;
335	            padding-left: 1rem;
336	            font-size: 110%;
337	            color: #080;
338	        }
339	
340	        a, a:visited
341	        {
342	            color: var(--link-color);
343	            text-decoration: none;
344	        }
345	
346	        #graph
347	        {
348	            display: none;
349	        }
350	
351	        /* This is for graph in svg */
352	        text
353	        {
354	            font-size: 14px;
355	            fill: var(--text-color);
356	        }
357	
358	        .node rect
359	        {
360	            fill: var(--element-background-color);
361	            filter: drop-shadow(.2rem .2rem .2rem var(--shadow-color));
362	        }
363	
364	        .edgePath path
365	        {
366	            stroke: var(--text-color);
367	        }
368	
369	        marker
370	        {
371	            fill: var(--text-color);
372	        }
373	
374	        #logo
375	        {
376	            fill: var(--logo-color);
377	        }
378	
379	        #logo:hover
380	        {
381	            fill: var(--logo-color-active);
382	        }
383	
384	        #logo-container
385	        {
386	            text-align: center;
387	            margin-top: 5em;
388	        }
