401	
402	                conditional(
403	                    ConstSource<NumericArraySource<T0>>(*col_left_const_array),
404	                    ConstSource<NumericArraySource<T1>>(*col_right_const_array),
405	                    NumericArraySink<ResultType>(arr_res.getData(), arr_res.getOffsets(), input_rows_count),
406	                    cond_col->getData());
407	
408	                return res;
409	            }
410	
411	            return nullptr;
412	        }
413	    }
