416	    ColumnPtr executeTyped(
417	        const ColumnUInt8 * cond_col, const ColumnsWithTypeAndName & arguments, const DataTypePtr & result_type, size_t input_rows_count) const
418	    {
419	        using ColVecT0 = ColumnVectorOrDecimal<T0>;
420	        using ColVecT1 = ColumnVectorOrDecimal<T1>;
421	
422	        const IColumn * col_left_untyped = arguments[1].column.get();
423	
424	        ColumnPtr right_column = nullptr;
425	
426	        if (const auto * col_left = checkAndGetColumn<ColVecT0>(col_left_untyped))
427	        {
428	            right_column = executeRightType<T0, T1, ColVecT0, ColVecT1>(cond_col, arguments, col_left);
429	        }
430	        else if (const auto * col_const_left = checkAndGetColumnConst<ColVecT0>(col_left_untyped))
431	        {
432	            right_column = executeConstRightType<T0, T1, ColVecT0, ColVecT1>(cond_col, arguments, col_const_left);
433	        }
434	        else if (const auto * col_arr_left = checkAndGetColumn<ColumnArray>(col_left_untyped))
435	        {
436	            if (auto col_arr_left_elems = checkAndGetColumn<ColVecT0>(&col_arr_left->getData()))
437	            {
438	                right_column = executeRightTypeArray<T0, T1, ColVecT0, ColVecT1>(
439	                    cond_col, arguments, result_type, col_arr_left, input_rows_count);
440	            }
441	        }
442	        else if (const auto * col_const_arr_left = checkAndGetColumnConst<ColumnArray>(col_left_untyped))
443	        {
