454	    static ColumnPtr executeString(const ColumnUInt8 * cond_col, const ColumnsWithTypeAndName & arguments, const DataTypePtr & result_type)
455	    {
456	        const IColumn * col_then_untyped = arguments[1].column.get();
457	        const IColumn * col_else_untyped = arguments[2].column.get();
458	
459	        const ColumnString * col_then = checkAndGetColumn<ColumnString>(col_then_untyped);
460	        const ColumnString * col_else = checkAndGetColumn<ColumnString>(col_else_untyped);
461	        const ColumnFixedString * col_then_fixed = checkAndGetColumn<ColumnFixedString>(col_then_untyped);
462	        const ColumnFixedString * col_else_fixed = checkAndGetColumn<ColumnFixedString>(col_else_untyped);
463	        const ColumnConst * col_then_const = checkAndGetColumnConst<ColumnString>(col_then_untyped);
464	        const ColumnConst * col_else_const = checkAndGetColumnConst<ColumnString>(col_else_untyped);
465	        const ColumnConst * col_then_const_fixed = checkAndGetColumnConst<ColumnFixedString>(col_then_untyped);
466	        const ColumnConst * col_else_const_fixed = checkAndGetColumnConst<ColumnFixedString>(col_else_untyped);
467	
468	        const PaddedPODArray<UInt8> & cond_data = cond_col->getData();
469	        size_t rows = cond_data.size();
470	
471	        if (isFixedString(result_type))
472	        {
473	            /// The result is FixedString.
474	
475	            auto col_res_untyped = result_type->createColumn();
476	            ColumnFixedString * col_res = assert_cast<ColumnFixedString *>(col_res_untyped.get());
477	            auto sink = FixedStringSink(*col_res, rows);
478	
479	            if (col_then_fixed && col_else_fixed)
480	                conditional(FixedStringSource(*col_then_fixed), FixedStringSource(*col_else_fixed), sink, cond_data);
481	            else if (col_then_fixed && col_else_const_fixed)
482	                conditional(FixedStringSource(*col_then_fixed), ConstSource<FixedStringSource>(*col_else_const_fixed), sink, cond_data);
483	            else if (col_then_const_fixed && col_else_fixed)
484	                conditional(ConstSource<FixedStringSource>(*col_then_const_fixed), FixedStringSource(*col_else_fixed), sink, cond_data);
485	            else if (col_then_const_fixed && col_else_const_fixed)
486	                conditional(ConstSource<FixedStringSource>(*col_then_const_fixed),
487	                            ConstSource<FixedStringSource>(*col_else_const_fixed), sink, cond_data);
488	            else
489	                return nullptr;
490	
491	            return col_res_untyped;
492	        }
493	
494	        if (isString(result_type))
495	        {
496	            /// The result is String.
497	
498	            auto col_res = ColumnString::create();
499	            auto sink = StringSink(*col_res, rows);
500	
501	            if (col_then && col_else)
502	                conditional(StringSource(*col_then), StringSource(*col_else), sink, cond_data);
503	            else if (col_then && col_else_const)
504	                conditional(StringSource(*col_then), ConstSource<StringSource>(*col_else_const), sink, cond_data);
505	            else if (col_then_const && col_else)
506	                conditional(ConstSource<StringSource>(*col_then_const), StringSource(*col_else), sink, cond_data);
507	            else if (col_then_const && col_else_const)
508	                conditional(ConstSource<StringSource>(*col_then_const), ConstSource<StringSource>(*col_else_const), sink, cond_data);
509	            else if (col_then && col_else_fixed)
510	                conditional(StringSource(*col_then), FixedStringSource(*col_else_fixed), sink, cond_data);
511	            else if (col_then_fixed && col_else)
512	                conditional(FixedStringSource(*col_then_fixed), StringSource(*col_else), sink, cond_data);
513	            else if (col_then_const && col_else_fixed)
514	                conditional(ConstSource<StringSource>(*col_then_const), FixedStringSource(*col_else_fixed), sink, cond_data);
515	            else if (col_then_fixed && col_else_const)
516	                conditional(FixedStringSource(*col_then_fixed), ConstSource<StringSource>(*col_else_const), sink, cond_data);
517	            else if (col_then && col_else_const_fixed)
518	                conditional(StringSource(*col_then), ConstSource<FixedStringSource>(*col_else_const_fixed), sink, cond_data);
519	            else if (col_then_const_fixed && col_else)
520	                conditional(ConstSource<FixedStringSource>(*col_then_const_fixed), StringSource(*col_else), sink, cond_data);
521	            else if (col_then_const && col_else_const_fixed)
522	                conditional(ConstSource<StringSource>(*col_then_const), ConstSource<FixedStringSource>(*col_else_const_fixed), sink, cond_data);
523	            else if (col_then_const_fixed && col_else_const)
524	                conditional(ConstSource<FixedStringSource>(*col_then_const_fixed), ConstSource<StringSource>(*col_else_const), sink, cond_data);
525	            else if (col_then_fixed && col_else_fixed)
526	                conditional(FixedStringSource(*col_then_fixed), FixedStringSource(*col_else_fixed), sink, cond_data);
527	            else if (col_then_fixed && col_else_const_fixed)
528	                conditional(FixedStringSource(*col_then_fixed), ConstSource<FixedStringSource>(*col_else_const_fixed), sink, cond_data);
529	            else if (col_then_const_fixed && col_else_fixed)
530	                conditional(ConstSource<FixedStringSource>(*col_then_const_fixed), FixedStringSource(*col_else_fixed), sink, cond_data);
531	            else if (col_then_const_fixed && col_else_const_fixed)
532	                conditional(ConstSource<FixedStringSource>(*col_then_const_fixed),
533	                            ConstSource<FixedStringSource>(*col_else_const_fixed), sink, cond_data);
534	            else
535	                return nullptr;
536	
537	            return col_res;
