773	    template <typename AnyColumnPtr>
774	    static ColumnPtr materializeColumnIfConst(const AnyColumnPtr & column)
775	    {
776	        return column->convertToFullColumnIfConst();
777	    }
778	
779	    static ColumnPtr makeNullableColumnIfNot(const ColumnPtr & column)
780	    {
781	        auto materialized = materializeColumnIfConst(column);
782	
783	        if (isColumnNullable(*materialized))
784	            return materialized;
785	
786	        return ColumnNullable::create(materialized, ColumnUInt8::create(column->size(), 0));
787	    }
