20	struct WelchTTestData : public TTestMoments<Float64>
21	{
22	    static constexpr auto name = "welchTTest";
23	
24	    bool hasEnoughObservations() const
25	    {
26	        return nx > 1 && ny > 1;
27	    }
28	
29	    Float64 getDegreesOfFreedom() const
30	    {
31	        Float64 mean_x = getMeanX();
32	        Float64 mean_y = getMeanY();
33	
34	        Float64 sx2 = (x2 + nx * mean_x * mean_x - 2 * mean_x * x1) / (nx - 1);
35	        Float64 sy2 = (y2 + ny * mean_y * mean_y - 2 * mean_y * y1) / (ny - 1);
36	
37	        Float64 numerator_sqrt = sx2 / nx + sy2 / ny;
38	        Float64 numerator = numerator_sqrt * numerator_sqrt;
39	
40	        Float64 denominator_x = sx2 * sx2 / (nx * nx * (nx - 1));
41	        Float64 denominator_y = sy2 * sy2 / (ny * ny * (ny - 1));
42	
43	        return numerator / (denominator_x + denominator_y);
44	    }
45	
46	    std::tuple<Float64, Float64> getResult() const
47	    {
48	        Float64 mean_x = getMeanX();
49	        Float64 mean_y = getMeanY();
50	
51	        /// t-statistic
52	        Float64 se = getStandardError();
53	        Float64 t_stat = (mean_x - mean_y) / se;
54	
55	        auto students_t_distribution = boost::math::students_t_distribution<Float64>(getDegreesOfFreedom());
56	        Float64 pvalue = 0;
57	        if (t_stat > 0)
58	            pvalue = 2 * boost::math::cdf<Float64>(students_t_distribution, -t_stat);
59	        else
60	            pvalue = 2 * boost::math::cdf<Float64>(students_t_distribution, t_stat);
61	
62	        return {t_stat, pvalue};
63	    }
64	};
