69	    assertBinary(name, argument_types);
70	
71	    if (parameters.size() > 1)
72	        throw Exception("Aggregate function " + name + " requires zero or one parameter.", ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH);
73	
74	    if (!isNumber(argument_types[0]) || !isNumber(argument_types[1]))
75	        throw Exception("Aggregate function " + name + " only supports numerical types", ErrorCodes::BAD_ARGUMENTS);
76	
77	    return std::make_shared<AggregateFunctionTTest<WelchTTestData>>(argument_types, parameters);
78	}
