438	
439	                checkTableStructure(zookeeper_path, metadata_snapshot);
440	
441	                Coordination::Stat metadata_stat;
442	                current_zookeeper->get(zookeeper_path + "/metadata", &metadata_stat);
443	                metadata_version = metadata_stat.version;
444	            }
