155	void WriteBufferFromS3::allocateBuffer()
156	{
157	    if (total_parts_uploaded != 0 && total_parts_uploaded % s3_settings.upload_part_size_multiply_parts_count_threshold == 0)
158	        upload_part_size *= s3_settings.upload_part_size_multiply_factor;
159	
160	    temporary_buffer = Aws::MakeShared<Aws::StringStream>("temporary buffer");
161	    temporary_buffer->exceptions(std::ios::badbit);
162	    last_part_size = 0;
163	}
