190	void WriteBufferFromS3::preFinalize()
191	{
192	    next();
193	
194	    if (multipart_upload_id.empty())
195	    {
196	        makeSinglepartUpload();
197	    }
198	    else
199	    {
200	        /// Write rest of the data as last part.
201	        writePart();
202	    }
203	
204	    is_prefinalized = true;
205	}
