218	void WriteBufferFromS3::createMultipartUpload()
219	{
220	    Aws::S3::Model::CreateMultipartUploadRequest req;
221	    req.SetBucket(bucket);
222	    req.SetKey(key);
223	
224	    /// If we don't do it, AWS SDK can mistakenly set it to application/xml, see https://github.com/aws/aws-sdk-cpp/issues/1840
225	    req.SetContentType("binary/octet-stream");
226	
227	    if (object_metadata.has_value())
228	        req.SetMetadata(object_metadata.value());
229	
230	    ProfileEvents::increment(for_disk_s3 ? ProfileEvents::DiskS3CreateMultipartUpload : ProfileEvents::S3CreateMultipartUpload);
231	
232	    auto outcome = client_ptr->CreateMultipartUpload(req);
233	
234	    if (outcome.IsSuccess())
235	    {
236	        multipart_upload_id = outcome.GetResult().GetUploadId();
237	        LOG_TRACE(log, "Multipart upload has created. Bucket: {}, Key: {}, Upload id: {}", bucket, key, multipart_upload_id);
238	    }
239	    else
240	        throw Exception(outcome.GetError().GetMessage(), ErrorCodes::S3_ERROR);
241	}
