333	void WriteBufferFromS3::fillUploadRequest(Aws::S3::Model::UploadPartRequest & req, int part_number)
334	{
335	    req.SetBucket(bucket);
336	    req.SetKey(key);
337	    req.SetPartNumber(part_number);
338	    req.SetUploadId(multipart_upload_id);
339	    req.SetContentLength(temporary_buffer->tellp());
340	    req.SetBody(temporary_buffer);
341	
342	    /// If we don't do it, AWS SDK can mistakenly set it to application/xml, see https://github.com/aws/aws-sdk-cpp/issues/1840
343	    req.SetContentType("binary/octet-stream");
344	}
