346	void WriteBufferFromS3::processUploadRequest(UploadPartTask & task)
347	{
348	    ProfileEvents::increment(for_disk_s3 ? ProfileEvents::DiskS3UploadPart : ProfileEvents::S3UploadPart);
349	
350	    auto outcome = client_ptr->UploadPart(task.req);
351	
352	    if (outcome.IsSuccess())
353	    {
354	        task.tag = outcome.GetResult().GetETag();
355	        LOG_TRACE(log, "Writing part finished. Bucket: {}, Key: {}, Upload_id: {}, Etag: {}, Parts: {}", bucket, key, multipart_upload_id, task.tag, part_tags.size());
356	    }
357	    else
358	        throw Exception(outcome.GetError().GetMessage(), ErrorCodes::S3_ERROR);
359	
360	    total_parts_uploaded++;
361	}
