198	    static llvm::Value * getValuePtrFromAggregateDataPtr(llvm::IRBuilderBase & builder, llvm::Value * aggregate_data_ptr)
199	    {
200	        llvm::IRBuilder<> & b = static_cast<llvm::IRBuilder<> &>(builder);
201	
202	        static constexpr size_t value_offset_from_structure = offsetof(SingleValueDataFixed<T>, value);
203	
204	        auto * type = toNativeType<T>(builder);
205	        auto * value_ptr_with_offset = b.CreateConstInBoundsGEP1_64(nullptr, aggregate_data_ptr, value_offset_from_structure);
206	        auto * value_ptr = b.CreatePointerCast(value_ptr_with_offset, type->getPointerTo());
207	
208	        return value_ptr;
209	    }
