211	    static llvm::Value * getValueFromAggregateDataPtr(llvm::IRBuilderBase & builder, llvm::Value * aggregate_data_ptr)
212	    {
213	        llvm::IRBuilder<> & b = static_cast<llvm::IRBuilder<> &>(builder);
214	
215	        auto * type = toNativeType<T>(builder);
216	        auto * value_ptr = getValuePtrFromAggregateDataPtr(builder, aggregate_data_ptr);
217	
