224	
225	        auto * has_value_ptr = b.CreatePointerCast(aggregate_data_ptr, b.getInt1Ty()->getPointerTo());
226	        b.CreateStore(b.getInt1(true), has_value_ptr);
227	
228	        auto * value_ptr = getValuePtrFromAggregateDataPtr(b, aggregate_data_ptr);
229	        b.CreateStore(value_to_check, value_ptr);
230	    }
