239	    static void compileChangeFirstTime(llvm::IRBuilderBase & builder, llvm::Value * aggregate_data_ptr, llvm::Value * value_to_check)
240	    {
241	        llvm::IRBuilder<> & b = static_cast<llvm::IRBuilder<> &>(builder);
242	
243	        auto * has_value_ptr = b.CreatePointerCast(aggregate_data_ptr, b.getInt1Ty()->getPointerTo());
244	        auto * has_value_value = b.CreateLoad(b.getInt1Ty(), has_value_ptr);
245	
246	        auto * head = b.GetInsertBlock();
247	
248	        auto * join_block = llvm::BasicBlock::Create(head->getContext(), "join_block", head->getParent());
249	        auto * if_should_change = llvm::BasicBlock::Create(head->getContext(), "if_should_change", head->getParent());
250	        auto * if_should_not_change = llvm::BasicBlock::Create(head->getContext(), "if_should_not_change", head->getParent());
251	
252	        b.CreateCondBr(has_value_value, if_should_not_change, if_should_change);
253	
254	        b.SetInsertPoint(if_should_not_change);
255	        b.CreateBr(join_block);
256	
257	        b.SetInsertPoint(if_should_change);
258	        compileChange(builder, aggregate_data_ptr, value_to_check);
259	        b.CreateBr(join_block);
260	
261	        b.SetInsertPoint(join_block);
262	    }
