322	    template <bool is_less>
323	    static void compileChangeComparison(llvm::IRBuilderBase & builder, llvm::Value * aggregate_data_ptr, llvm::Value * value_to_check)
324	    {
325	        llvm::IRBuilder<> & b = static_cast<llvm::IRBuilder<> &>(builder);
326	
327	        auto * has_value_ptr = b.CreatePointerCast(aggregate_data_ptr, b.getInt1Ty()->getPointerTo());
328	        auto * has_value_value = b.CreateLoad(b.getInt1Ty(), has_value_ptr);
329	
330	        auto * value = getValueFromAggregateDataPtr(b, aggregate_data_ptr);
331	
332	        auto * head = b.GetInsertBlock();
333	
334	        auto * join_block = llvm::BasicBlock::Create(head->getContext(), "join_block", head->getParent());
335	        auto * if_should_change = llvm::BasicBlock::Create(head->getContext(), "if_should_change", head->getParent());
336	        auto * if_should_not_change = llvm::BasicBlock::Create(head->getContext(), "if_should_not_change", head->getParent());
337	
338	        auto is_signed = std::numeric_limits<T>::is_signed;
339	
340	        llvm::Value * should_change_after_comparison = nullptr;
341	
342	        if constexpr (is_less)
343	        {
344	            if (value_to_check->getType()->isIntegerTy())
345	                should_change_after_comparison = is_signed ? b.CreateICmpSLT(value_to_check, value) : b.CreateICmpULT(value_to_check, value);
346	            else
347	                should_change_after_comparison = b.CreateFCmpOLT(value_to_check, value);
348	        }
349	        else
350	        {
351	            if (value_to_check->getType()->isIntegerTy())
352	                should_change_after_comparison = is_signed ? b.CreateICmpSGT(value_to_check, value) : b.CreateICmpUGT(value_to_check, value);
353	            else
354	                should_change_after_comparison = b.CreateFCmpOGT(value_to_check, value);
355	        }
356	
357	        b.CreateCondBr(b.CreateOr(b.CreateNot(has_value_value), should_change_after_comparison), if_should_change, if_should_not_change);
358	
359	        b.SetInsertPoint(if_should_change);
360	        compileChange(builder, aggregate_data_ptr, value_to_check);
361	        b.CreateBr(join_block);
362	
363	        b.SetInsertPoint(if_should_not_change);
364	        b.CreateBr(join_block);
365	
366	        b.SetInsertPoint(join_block);
367	    }
