455	/** For strings. Short strings are stored in the object itself, and long strings are allocated separately.
456	  * NOTE It could also be suitable for arrays of numbers.
457	  */
458	struct SingleValueDataString //-V730
459	{
460	private:
461	    using Self = SingleValueDataString;
462	
463	    Int32 size = -1;    /// -1 indicates that there is no value.
464	    Int32 capacity = 0;    /// power of two or zero
465	    char * large_data;
466	
467	public:
468	    static constexpr Int32 AUTOMATIC_STORAGE_SIZE = 64;
469	    static constexpr Int32 MAX_SMALL_STRING_SIZE = AUTOMATIC_STORAGE_SIZE - sizeof(size) - sizeof(capacity) - sizeof(large_data);
470	
471	private:
472	    char small_data[MAX_SMALL_STRING_SIZE]; /// Including the terminating zero.
473	
474	public:
475	    static constexpr bool is_nullable = false;
476	    static constexpr bool is_any = false;
477	
478	    bool has() const
479	    {
480	        return size >= 0;
481	    }
482	
483	    const char * getData() const
484	    {
485	        return size <= MAX_SMALL_STRING_SIZE ? small_data : large_data;
486	    }
487	
488	    StringRef getStringRef() const
489	    {
490	        return StringRef(getData(), size);
491	    }
492	
493	    void insertResultInto(IColumn & to) const
494	    {
495	        if (has())
496	            assert_cast<ColumnString &>(to).insertDataWithTerminatingZero(getData(), size);
497	        else
498	            assert_cast<ColumnString &>(to).insertDefault();
499	    }
500	
501	    void write(WriteBuffer & buf, const ISerialization & /*serialization*/) const
502	    {
503	        writeBinary(size, buf);
504	        if (has())
505	            buf.write(getData(), size);
506	    }
507	
508	    void read(ReadBuffer & buf, const ISerialization & /*serialization*/, Arena * arena)
509	    {
510	        Int32 rhs_size;
511	        readBinary(rhs_size, buf);
512	
513	        if (rhs_size >= 0)
514	        {
515	            if (rhs_size <= MAX_SMALL_STRING_SIZE)
516	            {
517	                /// Don't free large_data here.
518	
519	                size = rhs_size;
520	
521	                if (size > 0)
522	                    buf.readStrict(small_data, size);
523	            }
524	            else
525	            {
526	                if (capacity < rhs_size)
527	                {
528	                    capacity = static_cast<Int32>(roundUpToPowerOfTwoOrZero(rhs_size));
529	                    /// It might happen if the size was too big and the rounded value does not fit a size_t
530	                    if (unlikely(capacity < rhs_size))
531	                        throw Exception(ErrorCodes::TOO_LARGE_STRING_SIZE, "String size is too big ({})", rhs_size);
532	
533	                    /// Don't free large_data here.
534	                    large_data = arena->alloc(capacity);
535	                }
536	
537	                size = rhs_size;
538	                buf.readStrict(large_data, size);
539	            }
540	        }
541	        else
542	        {
543	            /// Don't free large_data here.
544	            size = rhs_size;
545	        }
546	    }
547	
548	    /// Assuming to.has()
549	    void changeImpl(StringRef value, Arena * arena)
550	    {
551	        Int32 value_size = value.size;
552	
553	        if (value_size <= MAX_SMALL_STRING_SIZE)
554	        {
555	            /// Don't free large_data here.
556	            size = value_size;
557	
558	            if (size > 0)
559	                memcpy(small_data, value.data, size);
560	        }
561	        else
562	        {
563	            if (capacity < value_size)
564	            {
565	                /// Don't free large_data here.
566	                capacity = roundUpToPowerOfTwoOrZero(value_size);
567	                large_data = arena->alloc(capacity);
568	            }
569	
570	            size = value_size;
571	            memcpy(large_data, value.data, size);
572	        }
573	    }
574	
575	    void change(const IColumn & column, size_t row_num, Arena * arena)
576	    {
577	        changeImpl(assert_cast<const ColumnString &>(column).getDataAtWithTerminatingZero(row_num), arena);
578	    }
579	
580	    void change(const Self & to, Arena * arena)
581	    {
582	        changeImpl(to.getStringRef(), arena);
583	    }
584	
585	    bool changeFirstTime(const IColumn & column, size_t row_num, Arena * arena)
586	    {
587	        if (!has())
588	        {
589	            change(column, row_num, arena);
590	            return true;
591	        }
592	        else
593	            return false;
594	    }
595	
