11	  * For arguments with most significand bit set, result is n.
12	  * For other arguments, returns value, rounded up to power of two.
13	  */
14	inline size_t roundUpToPowerOfTwoOrZero(size_t n)
15	{
16	    // if MSB is set, return n, to avoid return zero
17	    if (unlikely(n >= 0x8000000000000000ULL))
18	        return n;
19	
20	    --n;
21	    n |= n >> 1;
22	    n |= n >> 2;
23	    n |= n >> 4;
24	    n |= n >> 8;
25	    n |= n >> 16;
26	    n |= n >> 32;
27	    ++n;
28	
29	    return n;
