101	/** Returns a mask that has '1' for `bits` LSB set:
102	  * maskLowBits<UInt8>(3) => 00000111
103	  */
104	template <typename T>
105	inline T maskLowBits(unsigned char bits)
106	{
107	    if (bits == 0)
108	    {
109	        return 0;
110	    }
