891	                                             Poco::Logger * logger, MergeTreeSettingsPtr table_settings)
892	{
893	    if (zookeeper->expired())
894	        throw Exception("Table was not dropped because ZooKeeper session has expired.", ErrorCodes::TABLE_WAS_NOT_DROPPED);
895	
896	    auto remote_replica_path = zookeeper_path + "/replicas/" + replica;
897	
898	    LOG_INFO(logger, "Removing replica {}, marking it as lost", remote_replica_path);
899	    /// Mark itself lost before removing, because the following recursive removal may fail
900	    /// and partially dropped replica may be considered as alive one (until someone will mark it lost)
901	    zookeeper->trySet(remote_replica_path + "/is_lost", "1");
902	
903	    /// NOTE: we should check for remote_replica_path existence,
904	    /// since otherwise DROP REPLICA will fail if the replica had been already removed.
905	    if (!zookeeper->exists(remote_replica_path))
906	    {
907	        LOG_INFO(logger, "Removing replica {} does not exist", remote_replica_path);
908	        return;
