912	        /// Remove "host" node first to mark replica as dropped (the choice is arbitrary,
913	        /// it could be any node without children that exists since ancient server versions and not re-created on startup)
914	        [[maybe_unused]] auto code = zookeeper->tryRemove(fs::path(remote_replica_path) / "host");
915	        assert(code == Coordination::Error::ZOK || code == Coordination::Error::ZNONODE);
