936	        ops.emplace_back(zkutil::makeRemoveRequest(remote_replica_path + "/log_pointer", -1));
937	        ops.emplace_back(zkutil::makeRemoveRequest(remote_replica_path + "/max_processed_insert_time", -1));
938	        ops.emplace_back(zkutil::makeRemoveRequest(remote_replica_path + "/min_unprocessed_insert_time", -1));
939	        ops.emplace_back(zkutil::makeRemoveRequest(remote_replica_path + "/metadata", -1));
940	        ops.emplace_back(zkutil::makeRemoveRequest(remote_replica_path + "/metadata_version", -1));
941	        ops.emplace_back(zkutil::makeRemoveRequest(remote_replica_path + "/mutation_pointer", -1));
942	        Coordination::Responses res;
943	        code = zookeeper->tryMulti(ops, res);
944	        if (code != Coordination::Error::ZOK)
945	            LOG_WARNING(logger, "Cannot quickly remove nodes without children: {} (replica: {}). Will remove recursively.",
946	                        Coordination::errorMessage(code), remote_replica_path);
947	
948	        /// And finally remove everything else recursively
949	        zookeeper->tryRemoveRecursive(remote_replica_path);
950	    }
951	
952	    /// It may left some garbage if replica_path subtree are concurrently modified
953	    if (zookeeper->exists(remote_replica_path))
954	        LOG_ERROR(logger, "Replica was not completely removed from ZooKeeper, {} still exists and may contain some garbage.", remote_replica_path);
955	
956	    /// Check that `zookeeper_path` exists: it could have been deleted by another replica after execution of previous line.
957	    Strings replicas;
958	    if (Coordination::Error::ZOK != zookeeper->tryGetChildren(zookeeper_path + "/replicas", replicas) || !replicas.empty())
959	        return;
960	
961	    LOG_INFO(logger, "{} is the last replica, will remove table", remote_replica_path);
962	
963	    /** At this moment, another replica can be created and we cannot remove the table.
964	      * Try to remove /replicas node first. If we successfully removed it,
965	      * it guarantees that we are the only replica that proceed to remove the table
966	      * and no new replicas can be created after that moment (it requires the existence of /replicas node).
967	      * and table cannot be recreated with new /replicas node on another servers while we are removing data,
968	      * because table creation is executed in single transaction that will conflict with remaining nodes.
969	      */
