972	    /// But recursive removal may fail in the middle of operation leaving some garbage in zookeeper_path, so
973	    /// we remove it on table creation if there is /dropped node. Creating thread may remove /dropped node created by
974	    /// removing thread, and it causes race condition if removing thread is not finished yet.
975	    /// To avoid this we also create ephemeral child before starting recursive removal.
976	    /// (The existence of child node does not allow to remove parent node).
977	    Coordination::Requests ops;
978	    Coordination::Responses responses;
979	    String drop_lock_path = zookeeper_path + "/dropped/lock";
980	    ops.emplace_back(zkutil::makeRemoveRequest(zookeeper_path + "/replicas", -1));
981	    ops.emplace_back(zkutil::makeCreateRequest(zookeeper_path + "/dropped", "", zkutil::CreateMode::Persistent));
982	    ops.emplace_back(zkutil::makeCreateRequest(drop_lock_path, "", zkutil::CreateMode::Ephemeral));
983	    Coordination::Error code = zookeeper->tryMulti(ops, responses);
984	
985	    if (code == Coordination::Error::ZNONODE || code == Coordination::Error::ZNODEEXISTS)
986	    {
987	        LOG_WARNING(logger, "Table {} is already started to be removing by another replica right now", remote_replica_path);
988	    }
989	    else if (code == Coordination::Error::ZNOTEMPTY)
990	    {
991	        LOG_WARNING(logger, "Another replica was suddenly created, will keep the table {}", remote_replica_path);
992	    }
993	    else if (code != Coordination::Error::ZOK)
994	    {
995	        zkutil::KeeperMultiException::check(code, ops, responses);
996	    }
997	    else
998	    {
999	        auto metadata_drop_lock = zkutil::EphemeralNodeHolder::existing(drop_lock_path, *zookeeper);
1000	        LOG_INFO(logger, "Removing table {} (this might take several minutes)", zookeeper_path);
1001	        removeTableNodesFromZooKeeper(zookeeper, zookeeper_path, metadata_drop_lock, logger);
1002	    }
1003	}
1004	
1005	bool StorageReplicatedMergeTree::removeTableNodesFromZooKeeper(zkutil::ZooKeeperPtr zookeeper,
1006	        const String & zookeeper_path, const zkutil::EphemeralNodeHolder::Ptr & metadata_drop_lock, Poco::Logger * logger)
1007	{
1008	    bool completely_removed = false;
1009	
1010	    /// NOTE /block_numbers/ actually is not flat, because /block_numbers/<partition_id>/ may have ephemeral children,
1011	    /// but we assume that all ephemeral block locks are already removed when table is being dropped.
1012	    static constexpr std::array flat_nodes = {"block_numbers", "blocks", "leader_election", "log", "mutations", "pinned_part_uuids"};
1013	
1014	    /// First try to remove paths that are known to be flat
1015	    for (const auto * node : flat_nodes)
1016	    {
1017	        bool removed_quickly = zookeeper->tryRemoveChildrenRecursive(fs::path(zookeeper_path) / node, /* probably flat */ true);
1018	        if (!removed_quickly)
1019	            LOG_WARNING(logger, "Failed to quickly remove node '{}' and its children, fell back to recursive removal (table: {})",
1020	                        node, zookeeper_path);
1021	    }
1022	
1023	    /// Then try to remove nodes that are known to have no children (and should always exist)
1024	    Coordination::Requests ops;
1025	    for (const auto * node : flat_nodes)
1026	        ops.emplace_back(zkutil::makeRemoveRequest(zookeeper_path + "/" + node, -1));
1027	
1028	    ops.emplace_back(zkutil::makeRemoveRequest(zookeeper_path + "/alter_partition_version", -1));
1029	    ops.emplace_back(zkutil::makeRemoveRequest(zookeeper_path + "/columns", -1));
1030	    ops.emplace_back(zkutil::makeRemoveRequest(zookeeper_path + "/metadata", -1));
1031	    ops.emplace_back(zkutil::makeRemoveRequest(zookeeper_path + "/table_shared_id", -1));
1032	    Coordination::Responses res;
1033	    auto code = zookeeper->tryMulti(ops, res);
1034	    if (code != Coordination::Error::ZOK)
1035	        LOG_WARNING(logger, "Cannot quickly remove nodes without children: {} (table: {}). Will remove recursively.",
1036	                    Coordination::errorMessage(code), zookeeper_path);
1037	
1038	    Strings children;
1039	    code = zookeeper->tryGetChildren(zookeeper_path, children);
1040	    if (code == Coordination::Error::ZNONODE)
1041	        throw Exception(ErrorCodes::LOGICAL_ERROR, "There is a race condition between creation and removal of replicated table. It's a bug");
1042	
1043	    for (const auto & child : children)
1044	    {
1045	        if (child != "dropped")
1046	            zookeeper->tryRemoveRecursive(fs::path(zookeeper_path) / child);
1047	    }
1048	
1049	    ops.clear();
1050	    Coordination::Responses responses;
1051	    ops.emplace_back(zkutil::makeRemoveRequest(metadata_drop_lock->getPath(), -1));
1052	    ops.emplace_back(zkutil::makeRemoveRequest(fs::path(zookeeper_path) / "dropped", -1));
1053	    ops.emplace_back(zkutil::makeRemoveRequest(zookeeper_path, -1));
1054	    code = zookeeper->tryMulti(ops, responses);
1055	
1056	    if (code == Coordination::Error::ZNONODE)
1057	    {
1058	        throw Exception(ErrorCodes::LOGICAL_ERROR, "There is a race condition between creation and removal of replicated table. It's a bug");
1059	    }

