849	void ZooKeeper::finalize(bool error_send, bool error_receive, const String & reason)
850	{
851	    /// If some thread (send/receive) already finalizing session don't try to do it
852	    bool already_started = finalization_started.test_and_set();
853	
854	    if (already_started)
855	        return;
856	
857	    LOG_INFO(log, "Finalizing session {}: finalization_started={}, queue_finished={}, reason={}",
858	             session_id, already_started, requests_queue.isFinished(), reason);
859	
860	    auto expire_session_if_not_expired = [&]
861	    {
862	        /// No new requests will appear in queue after finish()
863	        bool was_already_finished = requests_queue.finish();
864	        if (!was_already_finished)
865	            active_session_metric_increment.destroy();
866	    };
867	
868	    try
869	    {
870	        if (!error_send)
871	        {
872	            /// Send close event. This also signals sending thread to stop.
873	            try
874	            {
875	                close();
876	            }
877	            catch (...)
878	            {
879	                /// This happens for example, when "Cannot push request to queue within operation timeout".
880	                /// Just mark session expired in case of error on close request, otherwise sendThread may not stop.
881	                expire_session_if_not_expired();
882	                tryLogCurrentException(log);
883	            }
884	
885	            /// Send thread will exit after sending close request or on expired flag
886	            if (send_thread.joinable())
887	                send_thread.join();
888	        }
889	
890	        /// Set expired flag after we sent close event
891	        expire_session_if_not_expired();
892	
893	        try
894	        {
895	            /// This will also wakeup the receiving thread.
896	            socket.shutdown();
897	        }
898	        catch (...)
899	        {
900	            /// We must continue to execute all callbacks, because the user is waiting for them.
901	            tryLogCurrentException(log);
902	        }
903	
904	        if (!error_receive && receive_thread.joinable())
905	            receive_thread.join();
906	
907	        {
908	            std::lock_guard lock(operations_mutex);
909	
910	            for (auto & op : operations)
911	            {
912	                RequestInfo & request_info = op.second;
913	                ZooKeeperResponsePtr response = request_info.request->makeResponse();
914	
915	                response->error = request_info.request->probably_sent
916	                    ? Error::ZCONNECTIONLOSS
917	                    : Error::ZSESSIONEXPIRED;
918	                response->xid = request_info.request->xid;
919	
920	                if (request_info.callback)
921	                {
922	                    try
923	                    {
924	                        request_info.callback(*response);
925	                        logOperationIfNeeded(request_info.request, response, true);
926	                    }
927	                    catch (...)
928	                    {
929	                        /// We must continue to all other callbacks, because the user is waiting for them.
930	                        tryLogCurrentException(log);
931	                    }
932	                }
933	            }
934	
935	            CurrentMetrics::sub(CurrentMetrics::ZooKeeperRequest, operations.size());
936	            operations.clear();
937	        }
938	
939	        {
940	            std::lock_guard lock(watches_mutex);
941	
942	            Int64 watch_callback_count = 0;
943	            for (auto & path_watches : watches)
944	            {
945	                WatchResponse response;
946	                response.type = SESSION;
947	                response.state = EXPIRED_SESSION;
948	                response.error = Error::ZSESSIONEXPIRED;
949	
950	                for (auto & callback : path_watches.second)
951	                {
952	                    watch_callback_count += 1;
953	                    if (callback)
954	                    {
955	                        try
956	                        {
957	                            callback(response);
958	                        }
959	                        catch (...)
960	                        {
961	                            tryLogCurrentException(log);
962	                        }
963	                    }
964	                }
965	            }
966	
967	            CurrentMetrics::sub(CurrentMetrics::ZooKeeperWatch, watch_callback_count);
968	            watches.clear();
969	        }
970	
971	        /// Drain queue
972	        RequestInfo info;
973	        while (requests_queue.tryPop(info))
974	        {
975	            if (info.callback)
976	            {
977	                ZooKeeperResponsePtr response = info.request->makeResponse();
978	                if (response)
979	                {
980	                    response->error = Error::ZSESSIONEXPIRED;
981	                    response->xid = info.request->xid;
982	                    try
983	                    {
984	                        info.callback(*response);
985	                        logOperationIfNeeded(info.request, response, true);
986	                    }
987	                    catch (...)
988	                    {
989	                        tryLogCurrentException(log);
990	                    }
991	                }
992	            }
993	            if (info.watch)
994	            {
995	                WatchResponse response;
996	                response.type = SESSION;
997	                response.state = EXPIRED_SESSION;
998	                response.error = Error::ZSESSIONEXPIRED;
999	                try
1000	                {
1001	                    info.watch(response);
1002	                }
1003	                catch (...)
1004	                {
1005	                    tryLogCurrentException(log);
1006	                }
1007	            }
1008	        }
1009	    }
1010	    catch (...)
1011	    {
1012	        tryLogCurrentException(log);
1013	    }
1014	}
