471	<script type="text/javascript">
472	
473	    /// Incremental request number. When response is received,
474	    /// if its request number does not equal to the current request number, response will be ignored.
475	    /// This is to avoid race conditions.
476	    let request_num = 0;
477	
478	    /// Save query in history only if it is different.
479	    let previous_query = '';
480	
481	    const current_url = new URL(window.location);
482	
483	    const server_address = current_url.searchParams.get('url');
484	    if (server_address) {
485	        document.getElementById('url').value = server_address;
486	    } else if (location.protocol != 'file:') {
487	        /// Substitute the address of the server where the page is served.
488	        document.getElementById('url').value = location.origin;
489	    }
490	
491	    /// Substitute user name if it's specified in the query string
492	    const user_from_url = current_url.searchParams.get('user');
493	    if (user_from_url) {
494	        document.getElementById('user').value = user_from_url;
495	    }
496	
497	    function postImpl(posted_request_num, query)
498	    {
499	        const user = document.getElementById('user').value;
500	        const password = document.getElementById('password').value;
501	
502	        const server_address = document.getElementById('url').value;
503	
504	        let url = server_address +
505	            (server_address.indexOf('?') >= 0 ? '&' : '?') +
506	            /// Ask server to allow cross-domain requests.
507	            'add_http_cors_header=1' +
508	            '&default_format=JSONCompact' +
509	            /// Safety settings to prevent results that browser cannot display.
510	            '&max_result_rows=1000&max_result_bytes=10000000&result_overflow_mode=break';
511	
512	        /// When the page is opened from a file, we cannot send custom HTTP headers,
513	        /// so we pass the credentials in the URL parameters instead.
514	        const use_url_credentials = location.protocol == 'file:';
515	        if (use_url_credentials) {
516	            url += '&user=' + encodeURIComponent(user) +
517	                '&password=' + encodeURIComponent(password);
518	        }
519	
520	        const xhr = new XMLHttpRequest;
521	
522	        xhr.open('POST', url, true);
523	
524	        /// Send the credentials in the "Authorization" header to avoid exposing them in URLs,
525	        /// which can be logged by proxies or saved in the browser history.
526	        if (!use_url_credentials) {
527	            xhr.setRequestHeader('Authorization', 'Basic ' + window.btoa(user + ':' + password));
528	        }
529	
530	        xhr.onreadystatechange = function()
531	        {
532	            if (posted_request_num != request_num) {
533	                return;
534	            } else if (this.readyState === XMLHttpRequest.DONE) {
535	                renderResponse(this.status, this.response);
536	
537	                /// The query is saved in browser history (in state JSON object)
538	                /// as well as in URL fragment identifier.
539	                if (query != previous_query) {
540	                    const state = {
541	                        query: query,
542	                        status: this.status,
543	                        response: this.response.length > 100000 ? null : this.response  /// Lower than the browser's limit.
544	                    };
545	                    const title = "ClickHouse Query: " + query;
546	
547	                    let history_url = window.location.pathname + '?user=' + encodeURIComponent(user);
548	                    if (server_address != location.origin) {
549	                        /// Save server's address in URL if it's not identical to the address of the play UI.
550	                        history_url += '&url=' + encodeURIComponent(server_address);
551	                    }
552	                    history_url += '#' + window.btoa(query);
553	
554	                    if (previous_query == '') {
555	                        history.replaceState(state, title, history_url);
556	                    } else {
557	                        history.pushState(state, title, history_url);
558	                    }
559	                    document.title = title;
560	                    previous_query = query;
561	                }
562	            } else {
563	                //console.log(this);
564	            }
565	        }
566	
567	        document.getElementById('check-mark').style.display = 'none';
568	        document.getElementById('hourglass').style.display = 'inline-block';
569	
570	        xhr.send(query);
571	    }
572	
573	    function renderResponse(status, response) {
574	        document.getElementById('hourglass').style.display = 'none';
575	
576	        if (status === 200) {
577	            let json;
578	            try { json = JSON.parse(response); } catch (e) {}
579	
580	            if (json !== undefined && json.statistics !== undefined) {
581	                renderResult(json);
582	            } else if (Array.isArray(json) && json.length == 2 &&
583	                Array.isArray(json[0]) && Array.isArray(json[1]) && json[0].length > 1 && json[0].length == json[1].length) {
584	                /// If user requested FORMAT JSONCompactColumns, we will render it as a chart.
585	                renderChart(json);
586	            } else {
587	                renderUnparsedResult(response);
588	            }
589	            document.getElementById('check-mark').style.display = 'inline';
590	        } else {
591	            /// TODO: Proper rendering of network errors.
592	            renderError(response);
593	        }
594	    }
595	
596	    window.onpopstate = function(event) {
597	        if (!event.state) {
598	            return;
599	        }
600	        document.getElementById('query').value = event.state.query;
601	        if (!event.state.response) {
602	            clear();
603	            return;
604	        }
605	        renderResponse(event.state.status, event.state.response);
606	    };
607	
608	    if (window.location.hash) {
609	        document.getElementById('query').value = window.atob(window.location.hash.substr(1));
610	    }
611	
612	    function post()
613	    {
614	        ++request_num;
615	        let query = document.getElementById('query').value;
616	        postImpl(request_num, query);
617	    }
618	
619	    document.getElementById('run').onclick = function()
620	    {
621	        post();
622	    }
623	
624	    document.onkeydown = function(event)
625	    {
626	        /// Firefox has code 13 for Enter and Chromium has code 10.
627	        if ((event.metaKey || event.ctrlKey) && (event.keyCode == 13 || event.keyCode == 10)) {
628	            post();
629	        }
630	    }
631	
632	    function clearElement(id)
633	    {
634	        let elem = document.getElementById(id);
635	        while (elem.firstChild) {
636	            elem.removeChild(elem.lastChild);
637	        }
638	        elem.style.display = 'none';
639	    }
640	
641	    function clear()
642	    {
643	        clearElement('data-table');
644	        clearElement('graph');
645	        clearElement('chart');
646	        clearElement('data-unparsed');
647	        clearElement('error');
648	        clearElement('hourglass');
649	
650	        document.getElementById('check-mark').innerText = '';
651	        document.getElementById('hourglass').innerText = '';
652	        document.getElementById('stats').innerText = '';
653	        document.getElementById('logo-container').style.display = 'block';
654	    }
655	
656	    function formatReadable(number = 0, decimals = 2, units = []) {
657	        const k = 1000;
658	        const i = number ? Math.floor(Math.log(number) / Math.log(k)) : 0;
659	        const unit = units[i];
660	        const dm = unit ? decimals : 0;
661	        return Number(number / Math.pow(k, i)).toFixed(dm) + unit;
662	    }
663	
664	    function formatReadableBytes(bytes) {
665	        const units = [' B', ' KB', ' MB', ' GB', ' TB', ' PB', ' EB', ' ZB', ' YB'];
666	
667	        return formatReadable(bytes, 2, units);
668	    }
669	
670	    function formatReadableRows(rows) {
671	        const units = ['', ' thousand', ' million', ' billion', ' trillion', ' quadrillion'];
672	
673	        return formatReadable(rows, 2, units);
674	    }
675	
676	    function renderResult(response)
677	    {
678	        clear();
679	
680	        let stats = document.getElementById('stats');
681	        const seconds = response.statistics.elapsed.toFixed(3);
682	        const rows = response.statistics.rows_read;
683	        const bytes = response.statistics.bytes_read;
684	        const formatted_bytes = formatReadableBytes(bytes);
685	        const formatted_rows = formatReadableRows(rows);
686	        stats.innerText = `Elapsed: ${seconds} sec, read ${formatted_rows} rows, ${formatted_bytes}.`;
687	
688	        /// We can also render graphs if user performed EXPLAIN PIPELINE graph=1 or EXPLAIN AST graph = 1
689	        if (response.data.length > 3 && document.getElementById('query').value.match(/^\s*EXPLAIN/i) && typeof(response.data[0][0]) === "string" && response.data[0][0].startsWith("digraph")) {
690	            renderGraph(response);
691	        } else {
692	            renderTable(response);
693	        }
694	    }
695	
696	    function renderCell(cell, col_idx, settings)
697	    {
698	        let td = document.createElement('td');
699	
700	        let is_null = (cell === null);
701	        let is_link = false;
702	
703	        /// Test: SELECT number, toString(number) AS str, number % 2 ? number : NULL AS nullable, range(number) AS arr, CAST((['hello', 'world'], [number, number % 2]) AS Map(String, UInt64)) AS map FROM numbers(10)
704	        let text;
705	        if (is_null) {
706	            text = 'ᴺᵁᴸᴸ';
707	        } else if (typeof(cell) === 'object') {
708	            text = JSON.stringify(cell);
709	        } else {
710	            text = cell;
711	
712	            /// If it looks like URL, create a link. This is for convenience.
713	            if (typeof(cell) == 'string' && cell.match(/^https?:\/\/\S+$/)) {
714	                is_link = true;
715	            }
716	        }
717	
718	        let node = document.createTextNode(text);
719	        if (is_link) {
720	            let link = document.createElement('a');
721	            link.appendChild(node);
722	            link.href = text;
723	            link.setAttribute('target', '_blank');
724	            node = link;
725	        }
726	
727	        if (settings.is_transposed) {
728	            td.className = 'left transposed';
729	        } else {
730	            td.className = settings.column_is_number[col_idx] ? 'right' : 'left';
731	        }
732	        if (is_null) {
733	            td.className += ' null';
734	        }
735	
736	        /// If it's a number, render bar in background.
737	        if (!settings.is_transposed && settings.column_need_render_bars[col_idx] && text > 0) {
738	            const ratio = 100 * text / settings.column_maximums[col_idx];
739	
740	            let div = document.createElement('div');
741	
742	            div.style.width = '100%';
743	            div.style.background = `linear-gradient(to right,
744	                var(--bar-color) 0%, var(--bar-color) ${ratio}%,
745	                transparent ${ratio}%, transparent 100%)`;
746	
747	            div.appendChild(node);
748	            node = div;
749	        }
750	
751	        td.appendChild(node);
752	        return td;
753	    }
754	
755	    function renderTableTransposed(response)
756	    {
757	        let tbody = document.createElement('tbody');
758	        for (let col_idx in response.meta) {
759	            let tr = document.createElement('tr');
760	            {
761	                let th = document.createElement('th');
762	                th.className = 'right';
763	                th.style.width = '0';
764	                th.appendChild(document.createTextNode(response.meta[col_idx].name));
765	                tr.appendChild(th);
766	            }
767	            for (let row_idx in response.data)
768	            {
769	                let cell = response.data[row_idx][col_idx];
770	                const td = renderCell(cell, col_idx, {is_transposed: true});
771	                tr.appendChild(td);
772	            }
773	            if (response.data.length == 0 && col_idx == 0)
774	            {
775	                /// If result is empty, show this fact with a style.
776	                let td = document.createElement('td');
777	                td.rowSpan = response.meta.length;
778	                td.className = 'empty-result';
779	                let div = document.createElement('div');
780	                div.appendChild(document.createTextNode("empty result"));
781	                div.className = 'empty-result';
782	                td.appendChild(div);
783	                tr.appendChild(td);
784	            }
785	            tbody.appendChild(tr);
786	        }
787	        let table = document.getElementById('data-table');
788	        table.appendChild(tbody);
789	        table.style.display = 'table';
790	    }
791	
792	    function renderTable(response)
793	    {
794	        if (response.data.length <= 1 && response.meta.length >= 5) {
795	            renderTableTransposed(response)
796	            return;
797	        }
798	
799	        let thead = document.createElement('thead');
800	        for (let idx in response.meta) {
801	            let th = document.createElement('th');
802	            const name = document.createTextNode(response.meta[idx].name);
803	            th.appendChild(name);
804	            thead.appendChild(th);
805	        }
806	
807	        /// To prevent hanging the browser, limit the number of cells in a table.
808	        /// It's important to have the limit on number of cells, not just rows, because tables may be wide or narrow.
809	        const max_rows = 10000 / response.meta.length;
810	        let row_num = 0;
811	
812	        const column_is_number = response.meta.map(elem => !!elem.type.match(/^(Nullable\()?(U?Int|Decimal|Float)/));
813	        const column_maximums = column_is_number.map((elem, idx) => elem ? Math.max(...response.data.map(row => row[idx])) : 0);
814	        const column_minimums = column_is_number.map((elem, idx) => elem ? Math.min(...response.data.map(row => Math.max(0, row[idx]))) : 0);
815	        const column_need_render_bars = column_is_number.map((elem, idx) => column_maximums[idx] > 0 && column_maximums[idx] > column_minimums[idx]);
816	
