8	/** Eliminate injective functions in the argument list of `uniq`-style aggregate functions.
9	  *
10	  * Injective functions do not change the number of distinct values,
11	  * so wrapping an argument of `uniq`, `uniqExact`, `uniqHLL12`, `uniqTheta`, `uniqCombined`, `uniqCombined64`
12	  * in an injective function does not affect the result and can be removed before execution.
13	  *
14	  * Example: SELECT uniq(f(x)) is rewritten into SELECT uniq(x) if f is injective.
15	  */
16	class UniqInjectiveFunctionsEliminationPass final : public IQueryTreePass
17	{
18	public:
19	    String getName() override { return "UniqInjectiveFunctionsEliminationPass"; }
20	
21	    String getDescription() override
22	    {
23	        return "Eliminate injective functions in the argument list of uniq* functions";
24	    }
25	
26	    void run(QueryTreeNodePtr query_tree_node, ContextPtr context) override;
27	};
