7	
8	#include <Interpreters/Context.h>
9	
10	namespace DB
11	{
12	
13	namespace
14	{
15	
16	/// `uniq`-style aggregate functions return the number of distinct argument values,
17	/// therefore injective functions applied to their arguments can be eliminated.
18	static const std::unordered_set<String> uniq_functions_names
19	    = {"uniq", "uniqExact", "uniqHLL12", "uniqTheta", "uniqCombined", "uniqCombined64"};
20	
21	class UniqInjectiveFunctionsEliminationVisitor : public InDepthQueryTreeVisitor<UniqInjectiveFunctionsEliminationVisitor>
22	{
23	public:
24	    explicit UniqInjectiveFunctionsEliminationVisitor(ContextPtr context_)
25	        : context(context_)
26	    {}
27	
28	    void enterImpl(QueryTreeNodePtr & node)
29	    {
30	        auto * function_node = node->as<FunctionNode>();
31	        if (!function_node || !function_node->isAggregateFunction())
32	            return;
33	
34	        if (!uniq_functions_names.contains(function_node->getFunctionName()))
35	            return;
36	
37	        for (auto & argument : function_node->getArguments().getNodes())
38	        {
39	            auto * argument_function_node = argument->as<FunctionNode>();
40	            if (!argument_function_node || !argument_function_node->isOrdinaryFunction())
41	                continue;
42	
43	            auto function = FunctionFactory::instance().tryGet(argument_function_node->getFunctionName(), context);
44	            if (!function || !function->isInjective({}))
45	                continue;
46	
47	            auto & inner_arguments = argument_function_node->getArguments().getNodes();
48	            if (inner_arguments.size() != 1)
49	                continue;
50	
51	            /// Replace `uniq(f(x))` with `uniq(x)` for injective `f`
52	            argument = inner_arguments[0];
53	        }
54	    }
55	
56	private:
57	    ContextPtr context;
58	};
59	
60	}
61	
62	void UniqInjectiveFunctionsEliminationPass::run(QueryTreeNodePtr query_tree_node, ContextPtr context)
63	{
64	    UniqInjectiveFunctionsEliminationVisitor visitor(context);
65	    visitor.visit(query_tree_node);
66	}
