518	void StorageReplicatedMergeTree::waitMutationToFinishOnReplicas(
519	    const Strings & replicas, const String & mutation_id) const
520	{
521	    if (replicas.empty())
522	        return;
523	
524	
525	    std::set<String> inactive_replicas;
526	    for (const String & replica : replicas)
527	    {
528	        LOG_DEBUG(log, "Waiting for {} to apply mutation {}", replica, mutation_id);
529	        zkutil::EventPtr wait_event = std::make_shared<Poco::Event>();
530	
531	        while (!partial_shutdown_called)
532	        {
533	            /// Mutation maybe killed or whole replica was deleted.
534	            /// Wait event will unblock at this moment.
535	            Coordination::Stat exists_stat;
536	            if (!getZooKeeper()->exists(fs::path(zookeeper_path) / "mutations" / mutation_id, &exists_stat, wait_event))
537	            {
538	                throw Exception(ErrorCodes::UNFINISHED, "Mutation {} was killed, manually removed or table was dropped", mutation_id);
539	            }
540	
541	            auto zookeeper = getZooKeeper();
542	            /// Replica could be inactive.
543	            if (!zookeeper->exists(fs::path(zookeeper_path) / "replicas" / replica / "is_active"))
544	            {
545	                LOG_WARNING(log, "Replica {} is not active during mutation. Mutation will be done asynchronously when replica becomes active.", replica);
546	
547	                inactive_replicas.emplace(replica);
548	                break;
549	            }
550	
551	            String mutation_pointer = fs::path(zookeeper_path) / "replicas" / replica / "mutation_pointer";
552	            std::string mutation_pointer_value;
553	            /// Replica could be removed
554	            if (!zookeeper->tryGet(mutation_pointer, mutation_pointer_value, nullptr, wait_event))
555	            {
556	                LOG_WARNING(log, "Replica {} was removed", replica);
557	                break;
558	            }
559	            else if (mutation_pointer_value >= mutation_id) /// Maybe we already processed more fresh mutation
560	                break;                                      /// (numbers like 0000000000 and 0000000001)
561	
562	            /// Replica can become inactive, so wait with timeout and recheck it
563	            if (wait_event->tryWait(1000))
564	                continue;
565	
566	            /// Here we check mutation for errors on local replica. If they happen on this replica
567	            /// they will happen on each replica, so we can check only in-memory info.
568	            auto mutation_status = queue.getIncompleteMutationsStatus(mutation_id);
569	            /// If mutation status is empty, than local replica may just not loaded it into memory.
570	            if (mutation_status && !mutation_status->latest_fail_reason.empty())
571	                break;
572	        }
573	
574	        /// This replica inactive, don't check anything
575	        if (!inactive_replicas.empty() && inactive_replicas.contains(replica))
576	            break;
577	
578	        /// It maybe already removed from zk, but local in-memory mutations
579	        /// state was not updated.
580	        if (!getZooKeeper()->exists(fs::path(zookeeper_path) / "mutations" / mutation_id))
581	        {
582	            throw Exception(ErrorCodes::UNFINISHED, "Mutation {} was killed, manually removed or table was dropped", mutation_id);
583	        }
584	
585	        if (partial_shutdown_called)
586	            throw Exception("Mutation is not finished because table shutdown was called. It will be done after table restart.",
587	                ErrorCodes::UNFINISHED);
588	
589	        /// Replica inactive, don't check mutation status
590	        if (!inactive_replicas.empty() && inactive_replicas.contains(replica))
591	            continue;
592	
593	        /// At least we have our current mutation
594	        std::set<String> mutation_ids;
595	        mutation_ids.insert(mutation_id);
596	
597	        /// Here we check mutation for errors or kill on local replica. If they happen on this replica
598	        /// they will happen on each replica, so we can check only in-memory info.
599	        auto mutation_status = queue.getIncompleteMutationsStatus(mutation_id, &mutation_ids);
600	        checkMutationStatus(mutation_status, mutation_ids);
601	    }
602	
603	    if (!inactive_replicas.empty())
604	    {
605	        throw Exception(ErrorCodes::UNFINISHED,
606	                        "Mutation is not finished because some replicas are inactive right now: {}. Mutation will be done asynchronously",
607	                        boost::algorithm::join(inactive_replicas, ", "));
608	    }
609	}
