378	static MutableColumns getMergedDataColumns(
379	    const Block & header,
380	    const SummingSortedAlgorithm::ColumnsDefinition & def)
381	{
382	    MutableColumns columns;
383	    size_t num_columns = def.column_numbers_not_to_aggregate.size() + def.columns_to_aggregate.size();
384	    columns.reserve(num_columns);
385	
386	    for (const auto & desc : def.columns_to_aggregate)
387	    {
388	        // Wrap aggregated columns in a tuple to match function signature
389	        if (!desc.is_agg_func_type && !desc.is_simple_agg_func_type && isTuple(desc.function->getReturnType()))
390	        {
391	            size_t tuple_size = desc.column_numbers.size();
392	            MutableColumns tuple_columns(tuple_size);
393	            for (size_t i = 0; i < tuple_size; ++i)
394	                tuple_columns[i] = header.safeGetByPosition(desc.column_numbers[i]).column->cloneEmpty();
395	
396	            columns.emplace_back(ColumnTuple::create(std::move(tuple_columns)));
397	        }
398	        else if (desc.is_simple_agg_func_type)
399	        {
400	            const auto & type = desc.nested_type ? desc.nested_type
401	                                                 : desc.real_type;
402	            columns.emplace_back(type->createColumn());
403	        }
404	        else
405	            columns.emplace_back(header.safeGetByPosition(desc.column_numbers[0]).column->cloneEmpty());
406	    }
407	
408	    for (const auto & column_number : def.column_numbers_not_to_aggregate)
409	        columns.emplace_back(header.safeGetByPosition(column_number).type->createColumn());
410	
411	    return columns;
412	}
