122	/// Returns true if merge result is not empty
123	static bool mergeMap(const SummingSortedAlgorithm::MapDescription & desc,
124	                     Row & row, const ColumnRawPtrs & raw_columns, size_t row_number)
125	{
126	    /// Strongly non-optimal.
127	
128	    Row & left = row;
129	    Row right(left.size());
130	
131	    for (size_t col_num : desc.key_col_nums)
132	        right[col_num] = (*raw_columns[col_num])[row_number].template get<Array>();
133	
134	    for (size_t col_num : desc.val_col_nums)
135	        right[col_num] = (*raw_columns[col_num])[row_number].template get<Array>();
136	
137	    auto at_ith_column_jth_row = [&](const Row & matrix, size_t i, size_t j) -> const Field &
138	    {
139	        return matrix[i].get<Array>()[j];
140	    };
141	
142	    auto tuple_of_nth_columns_at_jth_row = [&](const Row & matrix, const ColumnNumbers & col_nums, size_t j) -> Array
143	    {
144	        size_t size = col_nums.size();
145	        Array res(size);
146	        for (size_t col_num_index = 0; col_num_index < size; ++col_num_index)
147	            res[col_num_index] = at_ith_column_jth_row(matrix, col_nums[col_num_index], j);
148	        return res;
149	    };
150	
151	    std::map<Array, Array> merged;
152	
153	    auto accumulate = [](Array & dst, const Array & src)
154	    {
155	        bool has_non_zero = false;
156	        size_t size = dst.size();
157	        for (size_t i = 0; i < size; ++i)
158	            if (applyVisitor(FieldVisitorSum(src[i]), dst[i]))
159	                has_non_zero = true;
160	        return has_non_zero;
161	    };
162	
163	    auto merge = [&](const Row & matrix)
164	    {
165	        size_t rows = matrix[desc.key_col_nums[0]].get<Array>().size();
166	
167	        for (size_t j = 0; j < rows; ++j)
168	        {
169	            Array key = tuple_of_nth_columns_at_jth_row(matrix, desc.key_col_nums, j);
170	            Array value = tuple_of_nth_columns_at_jth_row(matrix, desc.val_col_nums, j);
171	
172	            auto it = merged.find(key);
173	            if (merged.end() == it)
174	                merged.emplace(std::move(key), std::move(value));
175	            else
176	            {
177	                if (!accumulate(it->second, value))
178	                    merged.erase(it);
179	            }
180	        }
181	    };
182	
183	    merge(left);
184	    merge(right);
185	
186	    for (size_t col_num : desc.key_col_nums)
187	        row[col_num] = Array(merged.size());
188	    for (size_t col_num : desc.val_col_nums)
189	        row[col_num] = Array(merged.size());
190	
191	    size_t row_num = 0;
192	    for (const auto & key_value : merged)
193	    {
194	        for (size_t col_num_index = 0, size = desc.key_col_nums.size(); col_num_index < size; ++col_num_index)
195	            row[desc.key_col_nums[col_num_index]].get<Array>()[row_num] = key_value.first[col_num_index];
196	
197	        for (size_t col_num_index = 0, size = desc.val_col_nums.size(); col_num_index < size; ++col_num_index)
198	            row[desc.val_col_nums[col_num_index]].get<Array>()[row_num] = key_value.second[col_num_index];
199	
200	        ++row_num;
201	    }
202	
203	    return row_num != 0;
204	}
