434	static void postprocessChunk(
435	    Chunk & chunk, size_t num_result_columns,
436	    const SummingSortedAlgorithm::ColumnsDefinition & def)
437	{
438	    size_t num_rows = chunk.getNumRows();
439	    auto columns = chunk.detachColumns();
440	
441	    Columns res_columns(num_result_columns);
442	    size_t next_column = 0;
443	
444	    for (const auto & desc : def.columns_to_aggregate)
445	    {
446	        auto column = std::move(columns[next_column]);
447	        ++next_column;
448	
449	        if (!desc.is_agg_func_type && !desc.is_simple_agg_func_type && isTuple(desc.function->getReturnType()))
450	        {
451	            /// Unpack tuple into block.
452	            size_t tuple_size = desc.column_numbers.size();
453	            for (size_t i = 0; i < tuple_size; ++i)
454	                res_columns[desc.column_numbers[i]] = assert_cast<const ColumnTuple &>(*column).getColumnPtr(i);
455	        }
456	        else if (desc.is_simple_agg_func_type && desc.nested_type)
457	        {
458	            const auto & from_type = desc.nested_type;
459	            const auto & to_type = desc.real_type;
460	            res_columns[desc.column_numbers[0]] = recursiveTypeConversion(column, from_type, to_type);
461	        }
462	        else
463	            res_columns[desc.column_numbers[0]] = std::move(column);
464	    }
465	
466	    for (auto column_number : def.column_numbers_not_to_aggregate)
467	    {
468	        auto column = std::move(columns[next_column]);
469	        ++next_column;
470	
471	        res_columns[column_number] = std::move(column);
472	    }
473	
474	    chunk.setColumns(std::move(res_columns), num_rows);
475	}
