477	static void setRow(Row & row, const ColumnRawPtrs & raw_columns, size_t row_num, const Names & column_names)
478	{
479	    size_t num_columns = row.size();
480	    for (size_t i = 0; i < num_columns; ++i)
481	    {
482	        try
483	        {
484	            raw_columns[i]->get(row_num, row[i]);
485	        }
486	        catch (...)
487	        {
488	            tryLogCurrentException(__PRETTY_FUNCTION__);
489	
490	            /// Find out the name of the column and throw more informative exception.
491	
492	            String column_name;
493	            if (i < column_names.size())
494	                column_name = column_names[i];
495	
496	            throw Exception("SummingSortedAlgorithm failed to read row " + toString(row_num)
497	                            + " of column " + toString(i) + (column_name.empty() ? "" : " (" + column_name + ")"),
498	                            ErrorCodes::CORRUPTED_DATA);
499	        }
500	    }
501	}
