520	void SummingSortedAlgorithm::SummingMergedData::startGroup(ColumnRawPtrs & raw_columns, size_t row)
521	{
522	    is_group_started = true;
523	
524	    setRow(current_row, raw_columns, row, def.column_names);
525	
526	    /// Reset aggregation states for next row
527	    for (auto & desc : def.columns_to_aggregate)
528	        desc.createState();
529	
530	    if (def.allocates_memory_in_arena && arena->size() > arena_size)
531	    {
532	        arena = std::make_unique<Arena>();
533	        arena_size = arena->size();
534	    }
535	
536	    if (def.maps_to_sum.empty())
537	    {
538	        /// We have only columns_to_aggregate. The status of current row will be determined
539	        /// in 'insertCurrentRowIfNeeded' method on the values of aggregate functions.
540	        current_row_is_zero = true; // NOLINT
541	    }
542	    else
543	    {
544	        /// We have complex maps that will be summed with 'mergeMap' method.
545	        /// The single row is considered non zero, and the status after merging with other rows
546	        /// will be determined in the branch below (when key_differs == false).
547	        current_row_is_zero = false; // NOLINT
548	    }
549	
550	    addRowImpl(raw_columns, row);
551	}
