553	void SummingSortedAlgorithm::SummingMergedData::finishGroup()
554	{
555	    is_group_started = false;
556	
557	    /// We have nothing to aggregate. It means that it could be non-zero, because we have columns_not_to_aggregate.
558	    if (def.columns_to_aggregate.empty())
559	        current_row_is_zero = false;
560	
561	    for (auto & desc : def.columns_to_aggregate)
562	    {
563	        // Do not insert if the aggregation state hasn't been created
564	        if (desc.created)
565	        {
566	            if (desc.is_agg_func_type)
567	            {
568	                current_row_is_zero = false;
569	            }
570	            else
571	            {
572	                try
573	                {
574	                    desc.function->insertResultInto(desc.state.data(), *desc.merged_column, arena.get());
575	
576	                    /// Update zero status of current row
577	                    if (!desc.is_simple_agg_func_type && desc.column_numbers.size() == 1)
578	                    {
579	                        // Flag row as non-empty if at least one column number if non-zero
580	                        current_row_is_zero = current_row_is_zero
581	                                              && desc.merged_column->isDefaultAt(desc.merged_column->size() - 1);
582	                    }
583	                    else
584	                    {
585	                        /// It is sumMapWithOverflow aggregate function.
586	                        /// Assume that the row isn't empty in this case
587	                        ///   (just because it is compatible with previous version)
588	                        current_row_is_zero = false;
589	                    }
590	                }
591	                catch (...)
592	                {
593	                    desc.destroyState();
594	                    throw;
595	                }
596	            }
597	            desc.destroyState();
598	        }
599	        else
600	            desc.merged_column->insertDefault();
601	    }
602	
603	    /// If it is "zero" row, then rollback the insertion
604	    /// (at this moment we need rollback only cols from columns_to_aggregate)
605	    if (current_row_is_zero)
606	    {
607	        for (auto & desc : def.columns_to_aggregate)
608	            desc.merged_column->popBack(1);
609	
610	        return;
611	    }
612	
613	    size_t next_column = columns.size() - def.column_numbers_not_to_aggregate.size();

