20	void TableFunctionFactory::registerFunction(const std::string & name, Value creator, CaseSensitiveness case_sensitiveness)
21	{
22	    if (!table_functions.emplace(name, creator).second)
23	        throw Exception("TableFunctionFactory: the table function name '" + name + "' is not unique",
24	            ErrorCodes::LOGICAL_ERROR);
25	
26	    if (case_sensitiveness == CaseInsensitive
27	        && !case_insensitive_table_functions.emplace(Poco::toLower(name), creator).second)
28	        throw Exception("TableFunctionFactory: the case insensitive table function name '" + name + "' is not unique",
29	                        ErrorCodes::LOGICAL_ERROR);
30	}
