32	TableFunctionPtr TableFunctionFactory::get(
33	    const ASTPtr & ast_function,
34	    ContextPtr context) const
35	{
36	    const auto * table_function = ast_function->as<ASTFunction>();
37	    auto res = tryGet(table_function->name, context);
38	    if (!res)
39	    {
40	        auto hints = getHints(table_function->name);
41	        if (!hints.empty())
42	            throw Exception(ErrorCodes::UNKNOWN_FUNCTION, "Unknown table function {}. Maybe you meant: {}", table_function->name , toString(hints));
43	        else
44	            throw Exception(ErrorCodes::UNKNOWN_FUNCTION, "Unknown table function {}", table_function->name);
45	    }
46	
47	    res->parseArguments(ast_function, context);
48	    return res;
49	}
50	
51	TableFunctionPtr TableFunctionFactory::tryGet(
52	        const std::string & name_param,
53	        ContextPtr) const
54	{
55	    String name = getAliasToOrName(name_param);
56	    TableFunctionPtr res;
57	
58	    auto it = table_functions.find(name);
59	    if (table_functions.end() != it)
60	        res = it->second();
61	    else
62	    {
63	        it = case_insensitive_table_functions.find(Poco::toLower(name));
64	        if (case_insensitive_table_functions.end() != it)
65	            res = it->second();
66	    }
67	
68	    if (!res)
69	        return nullptr;
70	
71	    if (CurrentThread::isInitialized())
72	    {
73	        auto query_context = CurrentThread::get().getQueryContext();
74	        if (query_context && query_context->getSettingsRef().log_queries)
75	            query_context->addQueryFactoriesInfo(Context::QueryLogFactories::TableFunction, name);
76	    }
77	
78	    return res;
79	}
