22	StoragePtr ITableFunction::execute(const ASTPtr & ast_function, ContextPtr context, const std::string & table_name,
23	                                   ColumnsDescription cached_columns, bool use_global_context) const
24	{
25	    ProfileEvents::increment(ProfileEvents::TableFunctionExecute);
26	
27	    AccessFlags required_access = getSourceAccessType();
28	    String function_name = getName();
29	    if ((function_name != "null") && (function_name != "view") && (function_name != "viewIfPermitted"))
30	        required_access |= AccessType::CREATE_TEMPORARY_TABLE;
31	    context->checkAccess(required_access);
32	
33	    auto context_to_use = use_global_context ? context->getGlobalContext() : context;
34	
35	    if (cached_columns.empty())
36	        return executeImpl(ast_function, context, table_name, std::move(cached_columns));
37	
38	    if (hasStaticStructure() && cached_columns == getActualTableStructure(context))
39	        return executeImpl(ast_function, context_to_use, table_name, std::move(cached_columns));
40	
41	    auto this_table_function = shared_from_this();
42	    auto get_storage = [=]() -> StoragePtr
43	    {
44	        return this_table_function->executeImpl(ast_function, context_to_use, table_name, cached_columns);
45	    };
46	
47	    /// It will request actual table structure and create underlying storage lazily
48	    return std::make_shared<StorageTableFunctionProxy>(StorageID(getDatabaseName(), table_name), std::move(get_storage),
49	                                                       std::move(cached_columns), needStructureConversion());
50	}
