117	bool DatabasePostgreSQL::checkPostgresTable(const String & table_name) const
118	{
119	    if (table_name.find('\'') != std::string::npos
120	        || table_name.find('\\') != std::string::npos)
121	    {
122	        throw Exception(ErrorCodes::BAD_ARGUMENTS,
123	            "PostgreSQL table name cannot contain single quote or backslash characters, passed {}", table_name);
124	    }
125	
126	    auto connection_holder = pool->get();
127	    pqxx::nontransaction tx(connection_holder->get());
128	
129	    try
130	    {
131	        /// Casting table_name::regclass throws pqxx::indefined_table exception if table_name is incorrect.
132	        pqxx::result result = tx.exec(fmt::format(
133	                    "SELECT '{}'::regclass, tablename "
134	                    "FROM pg_catalog.pg_tables "
135	                    "WHERE schemaname != 'pg_catalog' AND {} "
136	                    "AND tablename = '{}'",
137	                    formatTableName(table_name),
138	                    (configuration.schema.empty() ? "schemaname != 'information_schema'" : "schemaname = " + quoteString(configuration.schema)),
139	                    formatTableName(table_name)));
140	    }
141	    catch (pqxx::undefined_table const &)
142	    {
143	        return false;
144	    }
145	    catch (Exception & e)
146	    {
147	        e.addMessage("while checking postgresql table existence");
148	        throw;
149	    }
150	
151	    return true;
152	}
