177	StoragePtr DatabasePostgreSQL::fetchTable(const String & table_name, ContextPtr, bool table_checked) const
178	{
179	    if (!cache_tables || !cached_tables.contains(table_name))
180	    {
181	        if (!table_checked && !checkPostgresTable(table_name))
182	            return StoragePtr{};
183	
184	        auto connection_holder = pool->get();
185	        auto columns_info = fetchPostgreSQLTableStructure(connection_holder->get(), table_name, configuration.schema).physical_columns;
186	
187	        if (!columns_info)
188	            return StoragePtr{};
189	
190	        auto storage = std::make_shared<StoragePostgreSQL>(
191	                StorageID(database_name, table_name), pool, table_name,
192	                ColumnsDescription{columns_info->columns}, ConstraintsDescription{}, String{}, configuration.schema, configuration.on_conflict);
193	
194	        if (cache_tables)
195	            cached_tables[table_name] = storage;
196	
197	        return storage;
198	    }
199	
200	    if (table_checked || checkPostgresTable(table_name))
201	    {
202	        return cached_tables[table_name];
203	    }
204	
205	    /// Table does not exist anymore
206	    cached_tables.erase(table_name);
207	    return StoragePtr{};
208	}
