211	void DatabasePostgreSQL::attachTable(ContextPtr /* context_ */, const String & table_name, const StoragePtr & storage, const String &)
212	{
213	    std::lock_guard<std::mutex> lock{mutex};
214	
215	    if (!checkPostgresTable(table_name))
216	        throw Exception(ErrorCodes::UNKNOWN_TABLE,
217	                        "Cannot attach PostgreSQL table {} because it does not exist in PostgreSQL",
218	                        getTableNameForLogs(table_name), database_name);
219	
220	    if (!detached_or_dropped.contains(table_name))
221	        throw Exception(ErrorCodes::TABLE_ALREADY_EXISTS,
222	                        "Cannot attach PostgreSQL table {} because it already exists",
223	                        getTableNameForLogs(table_name), database_name);
224	
225	    if (cache_tables)
226	        cached_tables[table_name] = storage;
227	
228	    detached_or_dropped.erase(table_name);
229	
230	    fs::path table_marked_as_removed = fs::path(getMetadataPath()) / (escapeForFileName(table_name) + suffix);
231	    if (fs::exists(table_marked_as_removed))
232	        fs::remove(table_marked_as_removed);
