293	void DatabasePostgreSQL::loadStoredObjects(ContextMutablePtr /* context */, bool, bool /*force_attach*/, bool /* skip_startup_tables */)
294	{
295	    {
296	        std::lock_guard<std::mutex> lock{mutex};
297	        fs::directory_iterator iter(getMetadataPath());
298	
299	        /// Check for previously dropped tables
300	        for (fs::directory_iterator end; iter != end; ++iter)
301	        {
302	            if (fs::is_regular_file(iter->path()) && endsWith(iter->path().filename(), suffix))
303	            {
304	                const auto & file_name = iter->path().filename().string();
305	                const auto & table_name = unescapeForFileName(file_name.substr(0, file_name.size() - strlen(suffix)));
306	                detached_or_dropped.emplace(table_name);
307	            }
308	        }
309	    }
310	
311	    cleaner_task->activateAndSchedule();
