314	
315	void DatabasePostgreSQL::removeOutdatedTables()
316	{
317	    std::lock_guard<std::mutex> lock{mutex};
318	    auto connection_holder = pool->get();
319	    auto actual_tables = fetchPostgreSQLTablesList(connection_holder->get(), configuration.schema);
320	
321	    if (cache_tables)
322	    {
323	        /// (Tables are cached only after being accessed at least once)
324	        for (auto iter = cached_tables.begin(); iter != cached_tables.end();)
325	        {
326	            if (!actual_tables.contains(iter->first))
327	                iter = cached_tables.erase(iter);
328	            else
329	                ++iter;
330	        }
331	    }
332	
333	    for (auto iter = detached_or_dropped.begin(); iter != detached_or_dropped.end();)
334	    {
335	        if (!actual_tables.contains(*iter))
336	        {
337	            auto table_name = *iter;
338	            iter = detached_or_dropped.erase(iter);
339	            fs::path table_marked_as_removed = fs::path(getMetadataPath()) / (escapeForFileName(table_name) + suffix);
340	            if (fs::exists(table_marked_as_removed))
341	                fs::remove(table_marked_as_removed);
342	        }
343	        else
344	            ++iter;
345	    }
346	
347	    cleaner_task->scheduleAfter(cleaner_reschedule_ms);
348	}
