370	ASTPtr DatabasePostgreSQL::getCreateTableQueryImpl(const String & table_name, ContextPtr local_context, bool throw_on_error) const
371	{
372	    StoragePtr storage;
373	    {
374	        std::lock_guard lock{mutex};
375	        storage = fetchTable(table_name, local_context, false);
376	    }
377	    if (!storage)
378	    {
379	        if (throw_on_error)
380	            throw Exception(ErrorCodes::UNKNOWN_TABLE, "PostgreSQL table {} does not exist", getTableNameForLogs(table_name));
381	
382	        return nullptr;
383	    }
384	
385	    auto create_table_query = std::make_shared<ASTCreateQuery>();
386	    auto table_storage_define = database_engine_define->clone();
387	    create_table_query->set(create_table_query->storage, table_storage_define);
388	
389	    auto columns_declare_list = std::make_shared<ASTColumns>();
390	    auto columns_expression_list = std::make_shared<ASTExpressionList>();
391	
392	    columns_declare_list->set(columns_declare_list->columns, columns_expression_list);
393	    create_table_query->set(create_table_query->columns_list, columns_declare_list);
394	
395	    /// init create query.
396	    auto table_id = storage->getStorageID();
397	    create_table_query->setTable(table_id.table_name);
398	    create_table_query->setDatabase(table_id.database_name);
399	
400	    auto metadata_snapshot = storage->getInMemoryMetadataPtr();
401	    for (const auto & column_type_and_name : metadata_snapshot->getColumns().getOrdinary())
402	    {
403	        const auto & column_declaration = std::make_shared<ASTColumnDeclaration>();
404	        column_declaration->name = column_type_and_name.name;
405	        column_declaration->type = getColumnDeclaration(column_type_and_name.type);
406	        columns_expression_list->children.emplace_back(column_declaration);
407	    }
408	
409	    ASTStorage * ast_storage = table_storage_define->as<ASTStorage>();
410	    ASTs storage_children = ast_storage->children;
411	    auto storage_engine_arguments = ast_storage->engine->arguments;
412	
413	    if (storage_engine_arguments->children.empty())
414	        throw Exception(ErrorCodes::BAD_ARGUMENTS, "Unexpected number of arguments: {}", storage_engine_arguments->children.size());
415	
416	    /// Check for named collection.
417	    if (typeid_cast<ASTIdentifier *>(storage_engine_arguments->children[0].get()))
418	    {
419	        storage_engine_arguments->children.push_back(makeASTFunction("equals", std::make_shared<ASTIdentifier>("table"), std::make_shared<ASTLiteral>(table_id.table_name)));
420	    }
421	    else
422	    {
423	        /// Remove extra engine argument (`schema` and `use_table_cache`)
424	        if (storage_engine_arguments->children.size() >= 5)
425	            storage_engine_arguments->children.resize(4);
426	
427	        /// Add table_name to engine arguments.
428	        if (storage_engine_arguments->children.size() >= 2)
429	            storage_engine_arguments->children.insert(storage_engine_arguments->children.begin() + 2, std::make_shared<ASTLiteral>(table_id.table_name));
430	    }
431	
432	    return create_table_query;
433	}
