231	            session_id = storage->getSessionID(session_id_request.session_timeout_ms);
232	            LOG_DEBUG(log, "Session ID response {} with timeout {}", session_id, session_id_request.session_timeout_ms);
233	            response->session_id = session_id;
234	            if (!responses_queue.push(response_for_session))
235	            {
236	                ProfileEvents::increment(ProfileEvents::KeeperCommitsFailed);
237	                throw Exception(ErrorCodes::SYSTEM_ERROR, "Could not push response with session id {} into responses queue", session_id);
238	            }
239	        }
240	    }
241	    else
242	    {
243	        std::lock_guard lock(storage_and_responses_lock);
244	        KeeperStorage::ResponsesForSessions responses_for_sessions = storage->processRequest(
245	            request_for_session.request, request_for_session.session_id, request_for_session.zxid);
246	        for (auto & response_for_session : responses_for_sessions)
247	            if (!responses_queue.push(response_for_session))
248	            {
249	                ProfileEvents::increment(ProfileEvents::KeeperCommitsFailed);
250	                throw Exception(
251	                    ErrorCodes::SYSTEM_ERROR,
252	                    "Could not push response with session id {} into responses queue",
253	                    response_for_session.session_id);
254	            }
255	
256	        if (digest_enabled && request_for_session.digest)
257	        {
258	            assertDigest(*request_for_session.digest, storage->getNodesDigest(true), *request_for_session.request, true);
259	        }
260	    }
261	
262	    ProfileEvents::increment(ProfileEvents::KeeperCommits);
263	    last_committed_idx = log_idx;
264	    return nullptr;
