121	    ContextPtr context,
122	    const ASTPtr & table_func_ptr)
123	{
124	    const auto & shards_info = cluster.getShardsInfo();
125	
126	    std::string fail_messages;
127	
128	    auto try_get_structure_from_shard = [&](const Cluster::ShardInfo & shard_info) -> std::optional<ColumnsDescription>
129	    {
130	        try
131	        {
132	            const auto & res = getStructureOfRemoteTableInShard(cluster, shard_info, table_id, context, table_func_ptr);
133	
134	            /// Expect at least some columns.
135	            /// This is a hack to handle the empty block case returned by Connection when skip_unavailable_shards is set.
136	            if (res.empty())
137	                return std::nullopt;
138	
139	            return res;
140	        }
141	        catch (const NetException &)
142	        {
143	            std::string fail_message = getCurrentExceptionMessage(false);
144	            fail_messages += fail_message + '\n';
145	            return std::nullopt;
146	        }
147	    };
148	
149	    /// Try local shards first to avoid unnecessary network connections (and timeouts) during structure resolution.
150	    for (const auto & shard_info : shards_info)
151	    {
152	        if (!shard_info.isLocal())
153	            continue;
154	
155	        if (auto res = try_get_structure_from_shard(shard_info))
156	            return *res;
157	    }
158	
159	    for (const auto & shard_info : shards_info)
160	    {
161	        if (shard_info.isLocal())
