54	    bool parseAuthenticationData(IParserBase::Pos & pos, Expected & expected, AuthenticationData & auth_data)
55	    {
56	        return IParserBase::wrapParseImpl(pos, [&]
57	        {
58	            if (ParserKeyword{"NOT IDENTIFIED"}.ignore(pos, expected))
59	            {
60	                auth_data = AuthenticationData{AuthenticationType::NO_PASSWORD};
61	                return true;
62	            }
63	
64	            if (!ParserKeyword{"IDENTIFIED"}.ignore(pos, expected))
65	                return false;
66	
67	            std::optional<AuthenticationType> type;
68	            bool expect_password = false;
69	            bool expect_hash = false;
70	            bool expect_ldap_server_name = false;
71	            bool expect_kerberos_realm = false;
72	            bool expect_common_names = false;
73	
74	            if (ParserKeyword{"WITH"}.ignore(pos, expected))
75	            {
76	                for (auto check_type : collections::range(AuthenticationType::MAX))
77	                {
78	                    if (ParserKeyword{AuthenticationTypeInfo::get(check_type).raw_name}.ignore(pos, expected))
79	                    {
80	                        type = check_type;
81	
82	                        if (check_type == AuthenticationType::LDAP)
83	                            expect_ldap_server_name = true;
84	                        else if (check_type == AuthenticationType::KERBEROS)
85	                            expect_kerberos_realm = true;
86	                        else if (check_type == AuthenticationType::SSL_CERTIFICATE)
87	                            expect_common_names = true;
88	                        else if (check_type != AuthenticationType::NO_PASSWORD)
89	                            expect_password = true;
90	
91	                        break;
92	                    }
93	                }
94	
95	                if (!type)
96	                {
97	                    if (ParserKeyword{"SHA256_HASH"}.ignore(pos, expected))
98	                    {
99	                        type = AuthenticationType::SHA256_PASSWORD;
100	                        expect_hash = true;
101	                    }
102	                    else if (ParserKeyword{"DOUBLE_SHA1_HASH"}.ignore(pos, expected))
103	                    {
104	                        type = AuthenticationType::DOUBLE_SHA1_PASSWORD;
105	                        expect_hash = true;
106	                    }
107	                    else
108	                        return false;
109	                }
110	            }
111	
112	            if (!type)
113	            {
114	                type = AuthenticationType::SHA256_PASSWORD;
115	                expect_password = true;
116	            }
117	
118	            String value;
119	            String parsed_salt;
120	            boost::container::flat_set<String> common_names;
121	            if (expect_password || expect_hash)
122	            {
123	                ASTPtr ast;
124	                if (!ParserKeyword{"BY"}.ignore(pos, expected) || !ParserStringLiteral{}.parse(pos, ast, expected))
125	                    return false;
126	                value = ast->as<const ASTLiteral &>().value.safeGet<String>();
127	
128	                if (expect_hash && type == AuthenticationType::SHA256_PASSWORD)
129	                {
130	                    if (ParserKeyword{"SALT"}.ignore(pos, expected) && ParserStringLiteral{}.parse(pos, ast, expected))
131	                    {
132	                        parsed_salt = ast->as<const ASTLiteral &>().value.safeGet<String>();
133	                    }
134	                }
135	            }
136	            else if (expect_ldap_server_name)
137	            {
138	                ASTPtr ast;
139	                if (!ParserKeyword{"SERVER"}.ignore(pos, expected) || !ParserStringLiteral{}.parse(pos, ast, expected))
140	                    return false;
141	
142	                value = ast->as<const ASTLiteral &>().value.safeGet<String>();
143	            }
144	            else if (expect_kerberos_realm)
145	            {
146	                if (ParserKeyword{"REALM"}.ignore(pos, expected))
147	                {
148	                    ASTPtr ast;
149	                    if (!ParserStringLiteral{}.parse(pos, ast, expected))
150	                        return false;
151	
152	                    value = ast->as<const ASTLiteral &>().value.safeGet<String>();
153	                }
154	            }
155	            else if (expect_common_names)
156	            {
157	                if (!ParserKeyword{"CN"}.ignore(pos, expected))
158	                    return false;
159	
160	                ASTPtr ast;
161	                if (!ParserList{std::make_unique<ParserStringLiteral>(), std::make_unique<ParserToken>(TokenType::Comma), false}.parse(pos, ast, expected))
162	                    return false;
163	
164	                for (const auto & ast_child : ast->children)
165	                    common_names.insert(ast_child->as<const ASTLiteral &>().value.safeGet<String>());
166	            }
167	
168	            auth_data = AuthenticationData{*type};
169	            if (auth_data.getType() == AuthenticationType::SHA256_PASSWORD)
170	            {
171	                if (!parsed_salt.empty())
172	                {
173	                    auth_data.setSalt(parsed_salt);
174	                }
175	                else if (expect_password)
176	                {
177	#if USE_SSL
178	                    ///generate and add salt here
179	                    ///random generator FIPS complaint
180	                    uint8_t key[32];
181	                    if (RAND_bytes(key, sizeof(key)) != 1)
182	                    {
183	                        char buf[512] = {0};
184	                        ERR_error_string_n(ERR_get_error(), buf, sizeof(buf));
185	                        throw Exception(ErrorCodes::OPENSSL_ERROR, "Cannot generate salt for password. OpenSSL {}", buf);
186	                    }
187	
188	                    String salt;
189	                    salt.resize(sizeof(key) * 2);
190	                    char * buf_pos = salt.data();
191	                    for (uint8_t k : key)
192	                    {
193	                        writeHexByteUppercase(k, buf_pos);
194	                        buf_pos += 2;
195	                    }
196	                    value.append(salt);
197	                    auth_data.setSalt(salt);
198	#else
199	                    ///if USE_SSL is not defined, Exception thrown later
200	#endif
201	                }
202	            }
203	            if (expect_password)
204	                auth_data.setPassword(value);
205	            else if (expect_hash)
206	                auth_data.setPasswordHashHex(value);
207	            else if (expect_ldap_server_name)
208	                auth_data.setLDAPServerName(value);
209	            else if (expect_kerberos_realm)
210	                auth_data.setKerberosRealm(value);
211	            else if (expect_common_names)
212	                auth_data.setSSLCertificateCommonNames(std::move(common_names));
213	
214	            return true;
215	        });
216	    }
