249	            }
250	
251	            if (ParserKeyword{"NAME"}.ignore(pos, expected))
252	            {
253	                ASTPtr ast;
254	                if (!ParserList{std::make_unique<ParserStringLiteral>(), std::make_unique<ParserToken>(TokenType::Comma), false}.parse(pos, ast, expected))
255	                    return false;
256	
257	                for (const auto & name_ast : ast->children)
