259	
260	                return true;
261	            }
262	
263	            if (ParserKeyword{"IP"}.ignore(pos, expected))
264	            {
265	                ASTPtr ast;
266	                if (!ParserList{std::make_unique<ParserStringLiteral>(), std::make_unique<ParserToken>(TokenType::Comma), false}.parse(pos, ast, expected))
267	                    return false;
268	
269	                for (const auto & subnet_ast : ast->children)
270	                    res_hosts.addSubnet(subnet_ast->as<const ASTLiteral &>().value.safeGet<String>());
271	
272	                return true;
273	            }
274	
275	            if (ParserKeyword{"LIKE"}.ignore(pos, expected))
276	            {
277	                ASTPtr ast;
278	                if (!ParserList{std::make_unique<ParserStringLiteral>(), std::make_unique<ParserToken>(TokenType::Comma), false}.parse(pos, ast, expected))
279	                    return false;
