401	bool ParserCreateUserQuery::parseImpl(Pos & pos, ASTPtr & node, Expected & expected)
402	{
403	    bool alter = false;
404	    if (attach_mode)
405	    {
406	        if (!ParserKeyword{"ATTACH USER"}.ignore(pos, expected))
407	            return false;
408	    }
409	    else
410	    {
411	        if (ParserKeyword{"ALTER USER"}.ignore(pos, expected))
412	            alter = true;
413	        else if (!ParserKeyword{"CREATE USER"}.ignore(pos, expected))
414	            return false;
415	    }
416	
417	    bool if_exists = false;
418	    bool if_not_exists = false;
419	    bool or_replace = false;
420	    if (alter)
421	    {
422	        if (ParserKeyword{"IF EXISTS"}.ignore(pos, expected))
423	            if_exists = true;
424	    }
425	    else
426	    {
427	        if (ParserKeyword{"IF NOT EXISTS"}.ignore(pos, expected))
428	            if_not_exists = true;
429	        else if (ParserKeyword{"OR REPLACE"}.ignore(pos, expected))
430	            or_replace = true;
431	    }
432	
433	    ASTPtr names_ast;
434	    if (!ParserUserNamesWithHost{}.parse(pos, names_ast, expected))
435	        return false;
436	    auto names = typeid_cast<std::shared_ptr<ASTUserNamesWithHost>>(names_ast);
437	    auto names_ref = names->names;
438	
439	    std::optional<String> new_name;
440	    std::optional<AuthenticationData> auth_data;
441	    std::optional<AllowedClientHosts> hosts;
442	    std::optional<AllowedClientHosts> add_hosts;
443	    std::optional<AllowedClientHosts> remove_hosts;
444	    std::shared_ptr<ASTRolesOrUsersSet> default_roles;
445	    std::shared_ptr<ASTSettingsProfileElements> settings;
446	    std::shared_ptr<ASTRolesOrUsersSet> grantees;
447	    std::shared_ptr<ASTDatabaseOrNone> default_database;
448	    String cluster;
449	
450	    while (true)
451	    {
452	        if (!auth_data)
453	        {
454	            AuthenticationData new_auth_data;
455	            if (parseAuthenticationData(pos, expected, new_auth_data))
456	            {
457	                auth_data = std::move(new_auth_data);
458	                continue;
459	            }
460	        }
461	
462	        AllowedClientHosts new_hosts;
463	        if (parseHosts(pos, expected, "", new_hosts))
464	        {
465	            if (!hosts)
466	                hosts.emplace();
467	            hosts->add(new_hosts);
468	            continue;
469	        }
470	
471	        std::vector<std::shared_ptr<ASTSettingsProfileElement>> new_settings;
472	        if (parseSettings(pos, expected, attach_mode, new_settings))
473	        {
474	            if (!settings)
475	                settings = std::make_shared<ASTSettingsProfileElements>();
476	
477	            insertAtEnd(settings->elements, std::move(new_settings));
478	            continue;
479	        }
480	
481	        if (!default_roles && parseDefaultRoles(pos, expected, attach_mode, default_roles))
482	            continue;
483	
484	        if (cluster.empty() && parseOnCluster(pos, expected, cluster))
485	            continue;
486	
487	        if (!grantees && parseGrantees(pos, expected, attach_mode, grantees))
488	            continue;
489	
490	        if (!default_database && parseDefaultDatabase(pos, expected, default_database))
491	            continue;
492	
493	        if (alter)
494	        {
495	            String maybe_new_name;
496	            if (!new_name && (names->size() == 1) && parseRenameTo(pos, expected, new_name))
497	                continue;
498	
499	            if (parseHosts(pos, expected, "ADD", new_hosts))
500	            {
501	                if (!add_hosts)
502	                    add_hosts.emplace();
503	                add_hosts->add(new_hosts);
504	                continue;
505	            }
506	
507	            if (parseHosts(pos, expected, "DROP", new_hosts))
508	            {
509	                if (!remove_hosts)
510	                    remove_hosts.emplace();
511	                remove_hosts->add(new_hosts);
512	                continue;
513	            }
514	        }
515	
516	        break;
517	    }
518	
519	    if (!alter && !hosts)
520	    {
521	        String common_host_pattern;
522	        if (names->getHostPatternIfCommon(common_host_pattern) && !common_host_pattern.empty())
523	        {
524	            hosts.emplace().addLikePattern(common_host_pattern);
525	            names->concatParts();
526	        }
527	    }
528	    else if (alter)
529	        names->concatParts();
530	
531	    auto query = std::make_shared<ASTCreateUserQuery>();
532	    node = query;
533	
534	    query->alter = alter;
535	    query->attach = attach_mode;
536	    query->if_exists = if_exists;
537	    query->if_not_exists = if_not_exists;
538	    query->or_replace = or_replace;
539	    query->cluster = std::move(cluster);
540	    query->names = std::move(names);
541	    query->new_name = std::move(new_name);
542	    query->auth_data = std::move(auth_data);
543	    query->hosts = std::move(hosts);
544	    query->add_hosts = std::move(add_hosts);
545	    query->remove_hosts = std::move(remove_hosts);
546	    query->default_roles = std::move(default_roles);
547	    query->settings = std::move(settings);
548	    query->grantees = std::move(grantees);
549	    query->default_database = std::move(default_database);
550	
551	    return true;
552	}
