85	bool ReadBufferFromWebServer::nextImpl()
86	{
87	    if (read_until_position)
88	    {
89	        if (read_until_position == offset)
90	            return false;
91	
92	        if (read_until_position < offset)
93	            throw Exception(ErrorCodes::LOGICAL_ERROR, "Attempt to read beyond right offset ({} > {})", offset, read_until_position - 1);
94	    }
95	
96	    if (impl)
97	    {
98	        if (!use_external_buffer)
99	        {
100	            /**
101	            * impl was initialized before, pass position() to it to make
102	            * sure there is no pending data which was not read, because
103	            * this branch means we read sequentially.
104	            */
105	            impl->position() = position();
106	            assert(!impl->hasPendingData());
107	        }
108	    }
109	    else
110	    {
111	        impl = initialize();
112	    }
113	
114	    if (use_external_buffer)
115	    {
116	        /**
117	        * use_external_buffer -- means we read into the buffer which
118	        * was passed to us from somewhere else. We do not check whether
119	        * previously returned buffer was read or not, because this branch
120	        * means we are prefetching data, each nextImpl() call we can fill
121	        * a different buffer.
122	        */
123	        impl->set(internal_buffer.begin(), internal_buffer.size());
124	        assert(working_buffer.begin() != nullptr);
125	        assert(!internal_buffer.empty());
126	    }
127	
128	    auto result = impl->next();
129	    if (result)
130	    {
131	        BufferBase::set(impl->buffer().begin(), impl->buffer().size(), impl->offset());
132	        offset += working_buffer.size();
133	    }
134	
135	    return result;
