16	std::optional<std::string> MergeTreeIndexGranularityInfo::getMarksExtensionFromFilesystem(const DataPartStoragePtr & data_part_storage)
17	{
18	    if (data_part_storage->exists())
19	    {
20	        for (auto it = data_part_storage->iterate(); it->isValid(); it->next())
21	        {
22	            const auto & ext = fs::path(it->name()).extension();
23	            if (ext == getNonAdaptiveMrkExtension()
24	                || ext == getAdaptiveMrkExtension(MergeTreeDataPartType::Wide)
25	                || ext == getAdaptiveMrkExtension(MergeTreeDataPartType::Compact))
26	                return ext;
27	        }
28	    }
29	    return {};
30	}
