32	MergeTreeIndexGranularityInfo::MergeTreeIndexGranularityInfo(const MergeTreeData & storage, MergeTreeDataPartType type_)
33	    : type(type_)
34	{
35	    const auto storage_settings = storage.getSettings();
36	    fixed_index_granularity = storage_settings->index_granularity;
37	
38	    /// Granularity is fixed
39	    if (!storage.canUseAdaptiveGranularity())
40	    {
41	        if (type != MergeTreeDataPartType::Wide)
42	            throw Exception("Only Wide parts can be used with non-adaptive granularity.", ErrorCodes::NOT_IMPLEMENTED);
43	        setNonAdaptive();
44	    }
45	    else
46	        setAdaptive(storage_settings->index_granularity_bytes);
47	}
