49	void MergeTreeIndexGranularityInfo::changeGranularityIfRequired(const DataPartStoragePtr & data_part_storage)
50	{
51	    auto mrk_ext = getMarksExtensionFromFilesystem(data_part_storage);
52	    if (mrk_ext && *mrk_ext == getNonAdaptiveMrkExtension())
53	        setNonAdaptive();
