70	size_t MergeTreeIndexGranularityInfo::getMarkSizeInBytes(size_t columns_num) const
71	{
72	    if (type == MergeTreeDataPartType::Wide)
73	        return is_adaptive ? getAdaptiveMrkSizeWide() : getNonAdaptiveMrkSizeWide();
74	    else if (type == MergeTreeDataPartType::Compact)
75	        return getAdaptiveMrkSizeCompact(columns_num);
