103	    static ColumnPtr hashWithColumn(const DataTypePtr & data_type, const ColumnPtr & column, size_t pos, size_t limit)
104	    {
105	        WhichDataType which(data_type);
106	        if (which.isArray())
107	        {
108	            const auto * array_col = typeid_cast<const ColumnArray *>(column.get());
109	
110	            if (checkAndGetColumn<ColumnNullable>(array_col->getData()))
111	                throw Exception("Unexpected type " + data_type->getName() + " of bloom filter index.", ErrorCodes::BAD_ARGUMENTS);
112	
113	            const auto & offsets = array_col->getOffsets();
114	            limit = offsets[pos + limit - 1] - offsets[pos - 1];    /// PaddedPODArray allows access on index -1.
115	            pos = offsets[pos - 1];
116	
117	            if (limit == 0)
118	            {
119	                auto index_column = ColumnUInt64::create(1);
120	                ColumnUInt64::Container & index_column_vec = index_column->getData();
121	                index_column_vec[0] = 0;
122	                return index_column;
123	            }
124	        }
125	
126	        const ColumnPtr actual_col = BloomFilter::getPrimitiveColumn(column);
127	        const DataTypePtr actual_type = BloomFilter::getPrimitiveType(data_type);
128	
129	        auto index_column = ColumnUInt64::create(limit);
130	        ColumnUInt64::Container & index_column_vec = index_column->getData();
131	        getAnyTypeHash<true>(actual_type.get(), actual_col.get(), index_column_vec, pos);
132	        return index_column;
