165	    template <typename Type, bool is_first>
166	    static void getNumberTypeHash(const IColumn * column, ColumnUInt64::Container & vec, size_t pos)
167	    {
168	        const auto * index_column = typeid_cast<const ColumnVector<Type> *>(column);
169	
170	        if (unlikely(!index_column))
171	            throw Exception("Illegal column type was passed to the bloom filter index.", ErrorCodes::ILLEGAL_COLUMN);
172	
173	        const typename ColumnVector<Type>::Container & vec_from = index_column->getData();
174	
175	        /// Because we're missing the precision of float in the Field.h
176	        /// to be consistent, we need to convert Float32 to Float64 processing, also see: BloomFilterHash::hashWithField
177	        if constexpr (std::is_same_v<ColumnVector<Type>, ColumnFloat32>)
178	        {
179	            for (size_t index = 0, size = vec.size(); index < size; ++index)
180	            {
181	                UInt64 hash = DefaultHash64<Float64>(Float64(vec_from[index + pos]));
182	
183	                if constexpr (is_first)
184	                    vec[index] = hash;
185	                else
186	                    vec[index] = CityHash_v1_0_2::Hash128to64(CityHash_v1_0_2::uint128(vec[index], hash));
187	            }
188	        }
189	        else
190	        {
191	            for (size_t index = 0, size = vec.size(); index < size; ++index)
192	            {
193	                UInt64 hash = DefaultHash64<Type>(vec_from[index + pos]);
194	
195	                if constexpr (is_first)
196	                    vec[index] = hash;
197	                else
198	                    vec[index] = CityHash_v1_0_2::Hash128to64(CityHash_v1_0_2::uint128(vec[index], hash));
199	            }
200	        }
201	    }
