207	        {
208	            const ColumnString::Chars & data = index_column->getChars();
209	            const ColumnString::Offsets & offsets = index_column->getOffsets();
210	
211	            for (size_t index = 0, size = vec.size(); index < size; ++index)
212	            {
213	                ColumnString::Offset current_offset = offsets[index + pos - 1];
214	                size_t length = offsets[index + pos] - current_offset - 1 /* terminating zero */;
215	                UInt64 city_hash = CityHash_v1_0_2::CityHash64(
216	                    reinterpret_cast<const char *>(&data[current_offset]), length);
