16	    /// data types of set elements (two different Sets can be required for two tuples with the same contents
17	    /// if left hand sides of the IN operators have different types).
18	    static PreparedSetKey forLiteral(const IAST & ast, DataTypes types_)
19	    {
20	        /// Remove LowCardinality types from type list because Set doesn't support LowCardinality keys now,
21	        ///   just converts LowCardinality to ordinary types.
22	        for (auto & type : types_)
23	            type = recursiveRemoveLowCardinality(type);
24	
25	        PreparedSetKey key;
26	        key.ast_hash = ast.getTreeHash();
27	        key.types = std::move(types_);
28	        return key;
29	    }
