40	    IAST::Hash ast_hash;
41	    DataTypes types; /// Empty for subqueries.
42	
43	    bool operator==(const PreparedSetKey & other) const
44	    {
45	        if (ast_hash != other.ast_hash)
46	            return false;
47	
48	        if (types.size() != other.types.size())
49	            return false;
50	
51	        for (size_t i = 0; i < types.size(); ++i)
52	        {
53	            if (!types[i]->equals(*other.types[i]))
54	                return false;
55	        }
56	
57	        return true;
58	    }
59	
60	    struct Hash
61	    {
62	        UInt64 operator()(const PreparedSetKey & key) const { return key.ast_hash.first; }
63	    };
