CREATE TABLE prepared_set_shape_mismatch (a UInt64, b UInt64) ENGINE = MergeTree ORDER BY (a, b);

INSERT INTO prepared_set_shape_mismatch VALUES (1, 2), (3, 4);

-- The same set expression `(1, 2)` is used with a single column and with a tuple of two columns.
-- Preparing the set index for one of the IN expressions must not read past the bounds
-- of the set built for the other expression.
SELECT * FROM prepared_set_shape_mismatch WHERE a IN (1, 2) AND (a, b) IN (1, 2) ORDER BY a;
SELECT * FROM prepared_set_shape_mismatch WHERE (a, b) IN (1, 2) AND a IN (1, 2) ORDER BY a;

DROP TABLE prepared_set_shape_mismatch;

