863	{
864	    /// There is also the case when user has configured ClickHouse to wrong ZooKeeper cluster
865	    /// or metadata of staled replica were removed manually,
866	    /// in this case, has_metadata_in_zookeeper = false, and we also permit to drop the table.
867	
868	    bool maybe_has_metadata_in_zookeeper = has_metadata_in_zookeeper.load().value_or(true);
869	    if (maybe_has_metadata_in_zookeeper)
870	    {
871	        /// Table can be shut down, restarting thread is not active
872	        /// and calling StorageReplicatedMergeTree::getZooKeeper()/getAuxiliaryZooKeeper() won't suffice.
873	        zkutil::ZooKeeperPtr zookeeper;
874	        if (zookeeper_name == default_zookeeper_name)
875	            zookeeper = getContext()->getZooKeeper();
876	        else
877	            zookeeper = getContext()->getAuxiliaryZooKeeper(zookeeper_name);
878	
879	        /// If probably there is metadata in ZooKeeper, we don't allow to drop the table.
880	        if (!zookeeper)
881	            throw Exception("Can't drop readonly replicated table (need to drop data in ZooKeeper as well)", ErrorCodes::TABLE_IS_READ_ONLY);
882	
883	        shutdown();
884	        dropReplica(zookeeper, zookeeper_path, replica_name, log, getSettings());
885	    }
886	
887	    dropAllData();
888	}
