DROP TABLE IF EXISTS bloom_filter_idx;

CREATE TABLE bloom_filter_idx
(
    u UInt64,
    a Array(UInt8),
    INDEX bf (a) TYPE bloom_filter GRANULARITY 1
)
ENGINE = MergeTree
ORDER BY u;

INSERT INTO bloom_filter_idx SELECT number, [number] FROM numbers(10);

-- Literals that cannot be represented in the array element type must not trip
-- an internal assertion: the query degrades gracefully, and forcing the index
-- reports that it cannot be applied instead of crashing.
SELECT count() FROM bloom_filter_idx WHERE hasAll(a, [257]);
SELECT count() FROM bloom_filter_idx WHERE hasAll(a, [1]);
SELECT count() FROM bloom_filter_idx WHERE hasAll(a, [257]) SETTINGS force_data_skipping_indices = 'bf'; -- { serverError 277 }
SELECT count() FROM bloom_filter_idx WHERE hasAll(a, [1]) SETTINGS force_data_skipping_indices = 'bf';

DROP TABLE bloom_filter_idx;

